  Summon_117215_Desc = {
    Text = "Sự kiện có giới hạn thời gian, chỉ có thể đánh thức <SummonOrange:5> lần!"
  },
  Summon_117215_LongDesc1 = {
    Text = "[<SummonOrange:Lời gọi của dải ngân hà·Hỗ trợ>] Thức tỉnh Hợp đồng Mệnh quỹ đạo đã được mở. Trong thời gian mở, Người Giữ Gìn có thể từ đó thức tỉnh ngẫu nhiên 1 thể thức tỉnh SSR loại hỗ trợ từ Tinh Thần Thiên, 1 thể thức tỉnh SSR loại hỗ trợ từ Bài Quên, 1 vòng mệnh SSR đề xuất cho thể thức tỉnh loại hỗ trợ từ Tinh Thần Thiên, 2 vòng mệnh SSR đề xuất cho thể thức tỉnh loại hỗ trợ từ Bài Quên. \n· Mỗi Hợp đồng Mệnh quỹ đạo thức tỉnh sẽ đóng lại sau 5 lần thức tỉnh. \n· Trong hoạt động thức tỉnh Hợp đồng Mệnh quỹ đạo lần này, mỗi lần thức tỉnh sẽ chắc chắn nhận được một thể thức tỉnh SSR ngẫu nhiên hoặc một vòng mệnh SSR ngẫu nhiên. \n\n<Title:【Điều chỉnh cân bằng】>\n· Do cách chơi của trò chơi đặc biệt, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh. \n· Khi xảy ra việc giảm sút, trò chơi sẽ mở chức năng hồi tưởng có thời hạn để cho phép việc phát triển hoặc thức tỉnh của thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên. \n· Xin hãy chắc chắn rằng bạn đã hiểu và chấp nhận điều này trước khi đầu tư tài nguyên."
  },
  Summon_117215_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong【<SummonOrange:Lời gọi của dải ngân hà·Hỗ trợ>】thức tỉnh hợp đồng mệnh quỹ đạo, xác suất tổng hợp để nhận được vật phẩm SSR là 100.00%. Vật phẩm SSR nhận được là 2 thể thức tỉnh và 3 vòng mệnh.\n·Khi nhận được thể thức tỉnh SSR thông qua thức tỉnh, có 100% xác suất là thể thức tỉnh thuộc loại <SummonOrange:hỗ trợ>.\n\n<Title:【Giải thích đặc biệt】>\n·Dù thông qua bất kỳ phương thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, quà tặng từ hệ thống, v.v.) lần 2~16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ thể thức tỉnh tương ứng và 50 căn nguyên lắng đọng; lần 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tưởng linh hồn」× 1 và「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tưởng linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc thừa mảnh vỡ thể thức tỉnh thông qua bất kỳ phương thức tùy chọn nào (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, horizon nguyên mẫu, v.v.) và phương thức ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên lãng, v.v.), sẽ không chuyển đổi căn nguyên lắng đọng."
  },
