  Summon_119600_ShortDesc = {
    Text = "Được thân thể được đánh thức chắc chắn là <SummonRed:thịt máu> giới vực"
  },
  Summon_119600_Title = {
    Text = "Khi dải ngân hà lấp lánh"
  },
  Summon_119601_Desc = {
    Text = "Mỗi <SummonRed:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_119601_LongDesc1 = {
    Text = "[<SummonRed:Hoạ Ảnh Cuồng Tâm>] Sự kiện thức tỉnh nhân vật giới hạn thời gian đã bắt đầu. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh nhân vật UP giới hạn thời gian <SummonRed:Pickman>.\n·Trong thời gian sự kiện, xác suất thức tỉnh thể thức tỉnh SSR giới hạn <SummonRed:Pickman> sẽ được tăng cường.\n\n·Trong sự kiện thức tỉnh giới hạn thời gian này, ngoài các quy tắc đặc biệt như tăng xác suất và bảo đảm, tất cả các thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định được mô tả.\n·Khuyến nghị thức tỉnh hàng ngày: Trong sự kiện thức tỉnh giới hạn thời gian này, Người Giữ Gìn có thể thức tỉnh một lần với giá ưu đãi 60 nguồn lỏng mỗi ngày, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều Chỉnh Cân Bằng]>\n·Do tính chất đặc biệt của lối chơi, nhằm đảm bảo niềm vui và công bằng trong trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự giảm sút, trò chơi sẽ kích hoạt chức năng hồi tố giới hạn thời gian để cho phép việc phát triển hoặc thức tỉnh của thể thức tỉnh, vòng mệnh có cơ hội tái phân bổ tài nguyên.\n·Xin hãy chắc chắn rằng bạn hiểu và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_119601_LongDesc2 = {
    Text = "<Title:【Vật phẩm SSR】>\nTrong Thức Tỉnh giới hạn sự kiện nhân vật【<SummonRed:Họa Yểm Cuồng Tâm>】, tỷ lệ cơ bản nhận được vật phẩm SSR là 3.03%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 5.02%. Vật phẩm SSR nhận được đều là Thể Thức Tỉnh, tối đa 30 lần thức tỉnh chắc chắn nhận được Thể Thức Tỉnh SSR thông qua bảo đáy.\n·Khi nhận được Thể Thức Tỉnh SSR thông qua thức tỉnh, có 33.33% xác suất là Thể Thức Tỉnh SSR UP kỳ này <SummonRed:Pickman>.\n·Nếu 2 lần thức tỉnh liên tiếp nhận được Thể Thức Tỉnh SSR không phải nhân vật tăng tỷ lệ kỳ này, thì lần thức tỉnh tiếp theo nhận được nhân vật SSR chắc chắn là nhân vật tăng tỷ lệ kỳ này.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải UP kỳ này.{s3}\n\n<Title:【Vật phẩm SR】>\nTrong Thức Tỉnh sự kiện nhân vật【<SummonRed:Họa Yểm Cuồng Tâm>】, tỷ lệ cơ bản nhận được vật phẩm SR là 15.85%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 25.00%. Vật phẩm SR trong thức tỉnh này đều là Mệnh Luân.\n·Tối đa 5 lần thức tỉnh chắc chắn nhận được vật phẩm SR trở lên thông qua bảo đáy, xác suất nhận được vật phẩm SR qua bảo đáy là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Lưu ý đặc biệt】>\n·Khi thức tỉnh nhận được Mệnh Luân SR, đồng thời nhận được 5 Ngưng Tụ Căn Nguyên làm sản phẩm phụ; khi nhận được Mệnh Luân R, đồng thời nhận được 1 Ngưng Tụ Căn Nguyên làm sản phẩm phụ.\n·Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi cửa hàng, hệ thống tặng, v.v.) lần thứ 2～16 nhận được cùng một Thể Thức Tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ Thể Thức Tỉnh tương ứng và 50 Ngưng Tụ Căn Nguyên; từ lần thứ 17 trở đi, Thể Thức Tỉnh SSR không giới hạn sẽ chuyển đổi thành 1 Mảnh Linh Hạch Tinh Túy, 3 Mảnh Linh Hạch và「Ngưng Tụ Căn Nguyên」× 150, Thể Thức Tỉnh SSR giới hạn sẽ chuyển đổi thành 2 Mảnh Linh Hạch Tinh Túy, 6 Mảnh Linh Hạch và 250 Ngưng Tụ Căn Nguyên. Tuy nhiên, khi nhận được Thể Thức Tỉnh hoặc mảnh vỡ Thể Thức Tỉnh dư thừa thông qua phương thức tự chọn (bao gồm Lạc Viên Nguyên Chất, Lõi Hồi Tố Linh Hồn, Thị Giới Nguyên Mẫu, v.v.) cũng như phương thức ngẫu nhiên (bao gồm Bắt Giữ Nguyên Chất·Thiên Lãng Quên, v.v.), sẽ không chuyển đổi Ngưng Tụ Căn Nguyên.\n·Thức tỉnh lần này thuộc【Thức Tỉnh Sự Kiện Nhân Vật】, trong bất kỳ【Thức Tỉnh Sự Kiện Nhân Vật】nào, số lần thức tỉnh bảo đáy sẽ được tích lũy chung, và được thống kê độc lập với số lần thức tỉnh bảo đáy của các loại thức tỉnh khác.\n\n"
  },
