  Summon_119629_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh chắc chắn nhận được đối tượng SR hoặc cao hơn"
  },
  Summon_119629_LongDesc1 = {
    Text = "[<SummonOrange:Tiên tri tuyệt đối>] sự kiện thức tỉnh hoạt động nhân vật có giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh nhân vật UP hoạt động giới hạn <SummonOrange:Tan chảy · Đóa>.\n· Trong thời gian sự kiện, xác suất thức tỉnh của thể thức tỉnh SSR giới hạn <SummonOrange:Tan chảy · Đóa> sẽ được tăng lên.\n\n· Trong sự kiện thức tỉnh có giới hạn thời gian này, ngoài các quy tắc đặc biệt như tăng xác suất hoặc bảo đảm, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định được nêu rõ.\n· Mỗi ngày được khuyến nghị thức tỉnh: Trong sự kiện thức tỉnh có giới hạn thời gian này, Người Giữ Gìn có thể thức tỉnh một lần với ưu đãi 60 nguồn lỏng mỗi ngày, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n· Do lối chơi đặc biệt của game, nhằm đảm bảo sự vui vẻ và công bằng trong game, có thể sẽ có các điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh và vòng mệnh.\n· Khi xảy ra việc giảm sức mạnh, game sẽ mở chức năng hồi phục có giới hạn thời gian để cho phép thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n· Vui lòng chắc chắn rằng bạn đã hiểu và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_119629_LongDesc2 = {
    Text = "<Title:【Vật phẩm SSR】>\nTrong Triệu Hồi giới hạn sự kiện nhân vật【<SummonOrange:Tiên Tri Tuyệt Đối>】, tỷ lệ cơ bản nhận được vật phẩm SSR là 3.03%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 5.02%. Vật phẩm SSR nhận được đều là Thể Thức Tỉnh, tối đa 30 lần triệu hồi chắc chắn nhận được Thể Thức Tỉnh SSR thông qua bảo đáy.\n·Khi nhận được Thể Thức Tỉnh SSR thông qua triệu hồi, có 33.33% xác suất là Thể Thức Tỉnh SSR UP kỳ này <SummonOrange:Dung Hủy·Doer>.\n·Nếu 2 lần triệu hồi liên tiếp nhận được Thể Thức Tỉnh SSR không phải nhân vật tăng tỷ lệ kỳ này, thì lần tiếp theo nhận được nhân vật SSR thông qua triệu hồi chắc chắn là nhân vật tăng tỷ lệ kỳ này.{s1}\n·Hiện tại đã {s2} lần liên tiếp nhận được nhân vật không phải UP kỳ này.{s3}\n\n<Title:【Vật phẩm SR】>\nTrong Triệu Hồi sự kiện nhân vật【<SummonOrange:Tiên Tri Tuyệt Đối>】, tỷ lệ cơ bản nhận được vật phẩm SR là 15.85%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 25.00%. Vật phẩm SR trong triệu hồi này đều là Mệnh Luân.\n·Tối đa 5 lần triệu hồi chắc chắn nhận được vật phẩm SR trở lên thông qua bảo đáy, xác suất nhận được vật phẩm SR thông qua bảo đáy là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Thuyết minh đặc biệt】>\n·Khi triệu hồi nhận được Mệnh Luân SR, đồng thời nhận được 5 Căn Nguyên Trầm Tích làm sản phẩm phụ; khi nhận được Mệnh Luân R, đồng thời nhận được 1 Căn Nguyên Trầm Tích làm sản phẩm phụ.\n·Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn triệu hồi, đổi cửa hàng, hệ thống tặng, v.v.) từ lần thứ 2~16 nhận được cùng một Thể Thức Tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 Mảnh Vỡ Thể Thức Tỉnh tương ứng và 50 Căn Nguyên Trầm Tích; từ lần thứ 17 trở đi, Thể Thức Tỉnh SSR không giới hạn sẽ chuyển đổi thành 1 Mảnh Tinh Túy Linh Hạch, 3 Mảnh Linh Hạch và「Căn Nguyên Trầm Tích」× 150, Thể Thức Tỉnh SSR giới hạn sẽ chuyển đổi thành 2 Mảnh Tinh Túy Linh Hạch, 6 Mảnh Linh Hạch và 250 Căn Nguyên Trầm Tích. Tuy nhiên, khi nhận được Thể Thức Tỉnh hoặc Mảnh Vỡ Thể Thức Tỉnh dư thừa thông qua phương thức tùy chọn (bao gồm Nguyên Chất Lạc Viên, Lõi Hồi Tố Linh Hồn, Nguyên Mẫu Thị Giới, v.v.) và phương thức ngẫu nhiên (bao gồm Nguyên Chất Bắt Giữ·Thiên Vong Quên, v.v.), sẽ không chuyển đổi Căn Nguyên Trầm Tích.\n·Triệu hồi lần này thuộc【Triệu Hồi Sự Kiện Nhân Vật】, trong bất kỳ【Triệu Hồi Sự Kiện Nhân Vật】nào, số lần triệu hồi bảo đáy sẽ được tích lũy chung, và được thống kê độc lập với số lần triệu hồi bảo đáy của các loại triệu hồi khác.\n\n"
  },
