  Summon_121425_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh chắc chắn nhận được đối tượng SR hoặc cao hơn"
  },
  Summon_121425_LongDesc1 = {
    Text = "【<SummonOrange:Vô Giới Không Hưởng>】giới vực neo được đánh thức đã mở. Trong thời gian hoạt động, Người Giữ Gìn có thể từ đó đánh thức thân thể được giới hạn của <SummonOrange:hỗn loạn> giới vực và vòng lệnh được đề xuất. \n·Trong hoạt động đánh thức có thời hạn này, ngoại trừ các quy tắc đặc biệt như tăng xác suất kích hoạt, bảo đảm, tất cả thân thể hoặc vòng lệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định mô tả. \n·Đánh thức được đề xuất hàng ngày: Trong hoạt động neo giới vực này, Người Giữ Gìn có thể đánh thức một lần với 60 nguyên dịch với ưu đãi và được tặng thêm 60 bạc tâm. \n\n<Title:【Điều Chỉnh Cân Bằng】>\n·Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm bớt hoặc tăng cường hiệu ứng trong thân thể được đánh thức và vòng lệnh. \n·Khi xảy ra giảm bớt, trò chơi sẽ mở chức năng hồi tưởng có thời hạn để cho phép việc nuôi dưỡng hoặc đánh thức thân thể và vòng lệnh có cơ hội tái phân bổ tài nguyên. \n·Xin hãy chắc chắn rằng bạn đã biết và chấp nhận điều này trước khiĐầu tư tài nguyên. \n\n"
  },
  Summon_121425_LongDesc2 = {
    Text = "<Title:【Vật phẩm SSR】>\n·Trong Triệu hồi Neo định Giới vực【<SummonOrange:Vô Giới Không Hưởng>】, tỷ lệ cơ bản nhận được vật phẩm SSR là 3.03%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 5.02%. Vật phẩm SSR nhận được là Thể Thức tỉnh hoặc Mệnh Luân, tối đa 30 lần triệu hồi chắc chắn nhận được Thể Thức tỉnh hoặc Mệnh Luân SSR thông qua bảo đáy.\n·Khi nhận được vật phẩm SSR thông qua triệu hồi, có 33.33% xác suất là Thể Thức tỉnh SSR.\n·Nếu 2 lần liên tiếp triệu hồi nhận được SSR là Mệnh Luân, thì lần tiếp theo nhận được SSR thông qua triệu hồi chắc chắn là Thể Thức tỉnh.\n·Nếu 2 lần liên tiếp triệu hồi nhận được SSR là Thể Thức tỉnh, thì lần tiếp theo nhận được SSR thông qua triệu hồi chắc chắn là Mệnh Luân.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được Thể Thức tỉnh SSR.{s3}\n·Hiện tại đã liên tiếp {s4} lần nhận được Mệnh Luân SSR.{s3}\n\n<Title:【Vật phẩm SR】>\n·Trong Triệu hồi sự kiện nhân vật【<SummonOrange:Vô Giới Không Hưởng>】, tỷ lệ cơ bản nhận được vật phẩm SR là 15.85%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 25.00%. Tất cả vật phẩm SR trong lần triệu hồi này đều là Mệnh Luân.\n·Tối đa 5 lần triệu hồi chắc chắn nhận được vật phẩm SR trở lên thông qua bảo đáy, xác suất nhận được vật phẩm SR thông qua bảo đáy là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Thuyết minh đặc biệt】>\n·Khi triệu hồi nhận được Mệnh Luân SSR, sẽ đồng thời nhận được 50 Căn Nguyên Trầm Tích làm sản phẩm phụ; khi triệu hồi nhận được Mệnh Luân SR, sẽ đồng thời nhận được 5 Căn Nguyên Trầm Tích làm sản phẩm phụ; khi nhận được Mệnh Luân R, sẽ đồng thời nhận được 1 Căn Nguyên Trầm Tích làm sản phẩm phụ.\n·Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn triệu hồi, đổi cửa hàng, hệ thống tặng v.v.) từ lần thứ 2~16 nhận được cùng một Thể Thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 Mảnh vỡ Thể Thức tỉnh tương ứng và 50 Căn Nguyên Trầm Tích; từ lần thứ 17 trở đi, Thể Thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 1 và「Căn Nguyên Trầm Tích」× 150, Thể Thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 2 và「Căn Nguyên Trầm Tích」× 250. Tuy nhiên khi nhận được Thể Thức tỉnh hoặc Mảnh vỡ Thể Thức tỉnh dư thừa thông qua phương thức tùy chọn (bao gồm Nguyên Chất Lạc Viên, Lõi Hồi Tố Linh Hồn, Nguyên Mẫu Thị Giới v.v.) và phương thức ngẫu nhiên (bao gồm Nguyên Chất Bổ Hoạch·Vong Khước Thiên v.v.), sẽ không chuyển đổi Căn Nguyên Trầm Tích.\n·Lần triệu hồi này thuộc【Triệu hồi Neo định Giới vực】, trong bất kỳ【Triệu hồi Neo định Giới vực】nào, số lần triệu hồi bảo đáy sẽ được tích lũy chung, và được thống kê độc lập với số lần triệu hồi bảo đáy của các loại triệu hồi khác.\n\n"
  },
