  Summon_124042_Title = {
    Text = "Hư Vô Chiếu"
  },
  Summon_124043_Desc = {
    Text = "Mỗi <SummonPurple:5> lần thức tỉnh bắt buộc có đối tượng cấp SR hoặc cao hơn"
  },
  Summon_124043_LongDesc1 = {
    Text = "[<SummonPurple:Chúa tể của gai nhọn>] Sự kiện hoạt động nhân vật có giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể đánh thức nhân vật UP giới hạn thời gian <SummonPurple:Vanda>.\n·Trong thời gian sự kiện, xác suất nhận được thể thức tỉnh SSR giới hạn <SummonPurple:Vanda> sẽ được tăng lên.\n·Trong sự kiện thức tỉnh giới hạn này, ngoài các quy tắc đặc biệt như tăng xác suất kích hoạt, bảo đảm, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo hướng dẫn quy tắc.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo niềm vui và tính công bằng, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự giảm sút, trò chơi sẽ mở chức năng hồi tưởng có giới hạn thời gian để cho thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n·Xin hãy chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_124043_LongDesc2 = {
    Text = "<Title:[SSR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật giới hạn【<SummonPurple:Chúa tể của gai nhọn>】, xác suất cơ bản để nhận vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR thông qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR thông qua thức tỉnh, có 33.33% xác suất nhận được thể thức tỉnh SSR <SummonPurple:Vanda> trong đợt này.\n· Nếu hai lần thức tỉnh liên tiếp nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất nâng cao trong đợt này, lần thức tỉnh tiếp theo chắc chắn sẽ nhận được nhân vật có xác suất nâng cao trong đợt này.{s1}\n· Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải là nhân vật UP trong đợt này.{s3}\n\n<Title:[SR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật【<SummonPurple:Chúa tể của gai nhọn>】, xác suất cơ bản để nhận vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong đợt này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Thông tin đặc biệt]>\n· Khi nhận được vòng mệnh SR thông qua thức tỉnh, sẽ nhận được 5 căn nguyên lắng đọng như một sản phẩm phụ; khi nhận được vòng mệnh R, sẽ nhận được 1 căn nguyên lắng đọng như một sản phẩm phụ.\n· Bất kể thông qua hình thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, quà tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 nhận được thể thức tỉnh SSR giống nhau, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và 「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh không giới hạn bằng cách tùy chọn (bao gồm Khu vui chơi nguyên chất, Lõi Trở Lại Linh Hồn, Horizon Nguyên mẫu, v.v.) và cách ngẫu nhiên (bao gồm Bắt giữ nguyên chất·Bài Quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về【hoạt động thức tỉnh nhân vật】, trong bất kỳ【hoạt động thức tỉnh nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
