  Summon_124975_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_124975_LongDesc1 = {
    Text = "[<SummonOrange:Mực dư trong vườn>] Sự kiện Vòng mệnh Thức tỉnh có giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh UP giới hạn sự kiện <SummonOrange:Hồi kết của bài thơ>.\n·Trong thời gian sự kiện, xác suất nhận được vòng mệnh SSR giới hạn <SummonOrange:Hồi kết của bài thơ> sẽ được nâng cao.\n·Trong lần thức tỉnh sự kiện giới hạn này, ngoài việc kích hoạt xác suất nâng cao, bảo đảm và các quy tắc đặc biệt khác, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể dựa theo quy định đã nêu.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do đặc thù cách chơi của trò chơi, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, có thể sẽ có điều chỉnh cân bằng làm yếu hoặc mạnh các hiệu ứng trong thể thức tỉnh và vòng mệnh.\n·Khi có sự làm yếu xảy ra, trò chơi sẽ mở tính năng hồi lưu có giới hạn thời gian để cho thể thức tỉnh và vòng mệnh có cơ hội tái bố trí tài nguyên.\n·Xin vui lòng chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_124975_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện vòng mệnh giới hạn【<SummonOrange:Mực dư trong vườn>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần hoán tỉnh chắc chắn sẽ nhận được vòng mệnh SSR thông qua bảo đảm.\n·Khi nhận được vòng mệnh SSR thông qua hoán tỉnh, có 50.00% xác suất là vòng mệnh SSR đang được UP trong kỳ này<SummonOrange:Hồi kết của bài thơ>.\n·Nếu vòng mệnh SSR nhận được từ lần hoán tỉnh trước không phải là vòng mệnh có xác suất nâng cao trong kỳ này, thì vòng mệnh SSR nhận được từ lần hoán tỉnh tiếp theo chắc chắn sẽ là vòng mệnh có xác suất nâng cao trong kỳ này.\n\n<Title:【SR vật phẩm】>\nTrong sự kiện hoán tỉnh vòng mệnh【<SummonOrange:Mực dư trong vườn>】, xác suất cơ bản để hoán tỉnh vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần hoán tỉnh này đều là vòng mệnh.\n·Tối đa 5 lần hoán tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n·Khi nhận được vòng mệnh SSR, sẽ đồng thời nhận được 50 căn nguyên lắng đọng làm sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ đồng thời nhận được 5 căn nguyên lắng đọng làm sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng làm sản phẩm phụ.\n·Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn ở hoán tỉnh, đổi trong cửa hàng, hệ thống tặng, v. v.) từ lần thứ 2~16 nhận được cùng một vòng mệnh SSR, mỗi lần sẽ tự động nâng cấp cấp độ xếp chồng và nhận được 「Căn nguyên lắng đọng」×50; từ lần thứ 17 trở đi, sẽ chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 1,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 2,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000. Tuy nhiên khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm Sách luân chuyển, Lõi hồi tố mệnh đồ, v. v.) cũng như phương thức ngẫu nhiên(bao gồm Định cách số mệnh·Thiên vong, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n·Lần hoán tỉnh này thuộc về【hoán tỉnh vòng mệnh】, trong bất kỳ lần【hoán tỉnh vòng mệnh】 nào, số lần hoán tỉnh bảo đảm sẽ được cộng dồn chung, và độc lập thống kê với số lần hoán tỉnh bảo đảm của các loại hoán tỉnh khác.\n"
  },
