  Summon_127172_Desc = {
    Text = "Mỗi <SummonRed:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_127172_LongDesc1 = {
    Text = "[<SummonRed:Hội Ảo Cuồng Tâm>] Sự kiện có giới hạn thời gian thức tỉnh nhân vật đã bắt đầu. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh nhân vật UP sự kiện giới hạn <SummonRed:Pickman>.\n· Trong thời gian sự kiện, xác suất thức tỉnh của thân thể SSR giới hạn <SummonRed:Pickman> sẽ được nâng cao.\n\n· Trong lần thức tỉnh sự kiện có giới hạn này, ngoài các quy tắc đặc biệt như nâng cao xác suất, bảo đảm, v.v., tất cả thân thể hoặc vòng mệnh sẽ sử dụng xác suất cơ bản, cụ thể sẽ theo quy định.\n\n<Title:【Điều chỉnh cân bằng】>\n· Do tính chất đặc biệt của cách chơi, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng để làm yếu hoặc tăng cường hiệu ứng của thân thể và vòng mệnh.\n· Khi xảy ra việc làm yếu, trò chơi sẽ kích hoạt chức năng hồi tố có giới hạn thời gian để cho phép phát triển hoặc thức tỉnh của thân thể và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n· Vui lòng đảm bảo rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_127172_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện hoạt động nhân vật giới hạn 【<SummonRed:Hội Họa Cuồng Tâm>】, xác suất cơ bản nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR thông qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR thông qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonRed:Pickman> của đợt này.\n· Nếu liên tiếp 2 lần thức tỉnh nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất nâng cao trong đợt này, thì lần thức tỉnh tiếp theo chắc chắn sẽ nhận được nhân vật có xác suất nâng cao trong đợt này. {s1}\n· Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải là nhân vật có xác suất nâng cao trong đợt này. {s3}\n\n<Title:【SR vật phẩm】>\nTrong sự kiện hoạt động thức tỉnh 【<SummonRed:Hội Họa Cuồng Tâm>】, xác suất cơ bản nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n· Khi nhận được vòng mệnh SR thông qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua cách nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, quà tặng từ hệ thống, v.v.) lần 2~16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ thể thức tỉnh tương ứng và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 1 và 「Căn Nguyên Lắng Đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 2 và「Căn Nguyên Lắng Đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh thừa thông qua cách chọn tùy ý (bao gồm Khu vui chơi nguyên chất, Lõi Trở Lại Linh Hồn, Horizon Nguyên mẫu, v.v.) và cách ngẫu nhiên (bao gồm Bắt giữ nguyên chất·Bài Quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về 【thức tỉnh hoạt động nhân vật】, trong bất kỳ 【thức tỉnh hoạt động nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác. \n\n"
  },
