  Summon_130361_Title = {
    Text = "Văn bản tạm thời"
  },
  Summon_131639_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh chắc chắn nhận được đối tượng SR hoặc cao hơn"
  },
  Summon_131639_LongDesc1 = {
    Text = "[<SummonOrange:Đèn dẫn đường đêm tối>] Thức tỉnh giới hạn thời gian của lựa chọn nhân vật đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể từ đó <SummonOrange:Tự do chọn lựa> số lượng nhất định của thể thức tỉnh để nhận được khả năng tăng lên. \n\n·Trong thời gian sự kiện, khả năng nhận được thể thức tỉnh đã chọn sẽ được tăng lên. \n·Trong sự kiện thức tỉnh giới hạn thời gian này, trừ các quy tắc đặc biệt như khả năng tăng lên, bảo đảm, v.v., tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định. \n\n<Title:【Điều chỉnh cân bằng】>\n·Do lối chơi của trò chơi đặc biệt, nhằm đảm bảo niềm vui và tính công bằng, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng trong thể thức tỉnh, vòng mệnh. \n·Khi xảy ra giảm sức mạnh, trò chơi sẽ kích hoạt chức năng hồi phục giới hạn thời gian để cho phép việc phát triển hoặc thức tỉnh thể thức tỉnh, vòng mệnh có cơ hội tái phân bổ tài nguyên. \n·Vui lòng đảm bảo rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên. \n\n"
  },
  Summon_131639_LongDesc2 = {
    Text = "<Title:【Vật phẩm SSR】>\nTrong Triệu hồi giới hạn tự chọn nhân vật【<SummonOrange:Đêm Tối Dẫn Đèn>】, tỷ lệ cơ bản nhận được vật phẩm SSR là 3.03%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 5.02%. Vật phẩm SSR nhận được là Thể Thức Tỉnh, tối đa 30 lần triệu hồi chắc chắn nhận được Thể Thức Tỉnh SSR thông qua bảo đáy.\n·Khi nhận được SSR thông qua triệu hồi, có 50% xác suất là SSR<SummonOrange: Thể Thức Tỉnh> được chọn trong kỳ này.\n·Nếu SSR nhận được trong lần triệu hồi này không phải là Thể Thức Tỉnh SSR được chọn trong kỳ, thì lần nhận SSR tiếp theo thông qua triệu hồi chắc chắn sẽ là Thể Thức Tỉnh SSR được chọn trong kỳ.{s1}\n·Hiện tại đã liên tục {s2} lần nhận được Thể Thức Tỉnh không phải của kỳ này.{s3}\n\n<Title:【Vật phẩm SR】>\nTrong Triệu hồi sự kiện【<SummonOrange:Đêm Tối Dẫn Đèn>】, tỷ lệ cơ bản nhận được vật phẩm SR là 15.85%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 25.00%. Tất cả vật phẩm SR trong triệu hồi này đều là Mệnh Luân.\n·Tối đa 5 lần triệu hồi chắc chắn nhận được vật phẩm SR trở lên thông qua bảo đáy, xác suất nhận được vật phẩm SR thông qua bảo đáy là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Thuyết minh đặc biệt】>Khi nhận được Mệnh Luân SR thông qua triệu hồi, sẽ đồng thời nhận được 5 Ngưng Tụ Căn Nguyên làm sản phẩm phụ; khi nhận được Mệnh Luân R, sẽ đồng thời nhận được 1 Ngưng Tụ Căn Nguyên làm sản phẩm phụ.\n·Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn triệu hồi, đổi tại cửa hàng, hệ thống tặng, v.v.) từ lần thứ 2~16 nhận được cùng một Thể Thức Tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ Thể Thức Tỉnh tương ứng và 50 Ngưng Tụ Căn Nguyên; từ lần thứ 17 trở đi, Thể Thức Tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 1 và 「Ngưng Tụ Căn Nguyên」× 150, Thể Thức Tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 2 và「Ngưng Tụ Căn Nguyên」× 250. Tuy nhiên, khi nhận được Thể Thức Tỉnh hoặc mảnh vỡ Thể Thức Tỉnh dư thừa thông qua phương thức tự chọn (bao gồm Lạc Viên Nguyên Chất, Lõi Hồi Tố Linh Hồn, Nguyên Mẫu Thị Giới, v.v.) cũng như phương thức ngẫu nhiên (bao gồm Bắt Nguyên Chất·Thiên Vong Quên, v.v.), sẽ không chuyển đổi Ngưng Tụ Căn Nguyên.\n·Triệu hồi lần này thuộc【Triệu hồi tự chọn nhân vật】, trong bất kỳ【Triệu hồi tự chọn nhân vật】nào, số lần bảo đáy triệu hồi sẽ được tích lũy chung, và được thống kê độc lập với số lần bảo đáy triệu hồi của các loại triệu hồi khác.\n\n"
  },
