  Summon_14132_Desc = {
    Text = "Mỗi <SummonRed:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_14132_LongDesc1 = {
    Text = "[<SummonRed:Con vật trả thù>] Sự kiện có giới hạn thời gian thức tỉnh nhân vật đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể đánh thức nhân vật UP sự kiện giới hạn <SummonRed:Dây máu · Hiro>.\n· Trong thời gian sự kiện, xác suất thức tỉnh của thể thức tỉnh SSR giới hạn <SummonRed:Dây máu · Hiro> sẽ được nâng cao.\n· Sau khi sự kiện kết thúc, thể thức tỉnh SSR giới hạn <SummonRed:Dây máu · Hiro> vẫn sẽ xuất hiện trong các sự kiện thức tỉnh nhân vật giới hạn từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào sự kiện thức tỉnh nhân vật thường trú [giới vực nghiên cứu].\n· Trong lần thức tỉnh sự kiện giới hạn này, ngoài các quy tắc đặc biệt như tăng xác suất kích hoạt, bảo đảm, tất cả các thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định đã nêu.\n· Đề xuất thức tỉnh hàng ngày: Trong lần thức tỉnh sự kiện giới hạn này, Người Giữ Gìn có thể thức tỉnh với giá ưu đãi 60 nguồn lỏng mỗi ngày, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n· Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, có thể sẽ có điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh, vòng mệnh.\n· Khi có sự giảm sút, trò chơi sẽ mở chức năng hồi tố có giới hạn thời gian để cho phép việc nuôi dưỡng hoặc thức tỉnh thể thức tỉnh, vòng mệnh có cơ hội tái phân bổ tài nguyên.\n· Vui lòng chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_14132_LongDesc2 = {
    Text = "<Title:[SSR vật phẩm]>\nTrong hoạt động nhân vật giới hạn【<SummonRed:Con vật trả thù>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh sẽ chắc chắn nhận được thể thức tỉnh SSR thông qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR thông qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonRed:Dây máu · Hiro> trong đợt này.\n· Nếu hai lần thức tỉnh liên tiếp nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất tăng trong đợt này, lần thức tỉnh tiếp theo sẽ chắc chắn nhận được nhân vật có xác suất tăng trong đợt này.{s1}\n· Hiện tại đã liên tiếp nhận được {s2} lần nhân vật không phải là nhân vật có xác suất tăng trong đợt này.{s3}\n\n<Title:[SR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật【<SummonRed:Con vật trả thù>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong đợt thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh sẽ chắc chắn nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n· Khi nhận được vòng mệnh SR thông qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, quà tặng từ hệ thống, v.v.), từ lần thứ 2 đến lần 16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và 「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR có giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Nhưng khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh bị tràn thông qua các phương thức tùy chọn (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, horizon nguyên mẫu, v.v.) và phương thức ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về【thức tỉnh hoạt động nhân vật】, trong bất kỳ【thức tỉnh hoạt động nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
