  Summon_141455_Title = {
    Text = "Tiếng thì thầm bí ẩn của Biển Tối"
  },
  Summon_141456_Desc = {
    Text = "Mỗi <SummonPurple:5> lần thức tỉnh bắt buộc có đối tượng cấp SR hoặc cao hơn"
  },
  Summon_141456_LongDesc1 = {
    Text = "【<SummonPurple:Cánh Chim Đen Tối>】Sự kiện nhân vật có thời hạn đã được mở. Trong thời gian sự kiện, Người giữ gìn có thể hoán tỉnh nhân vật UP có thời hạn<SummonPurple:Castor>.\n·Trong thời gian sự kiện, xác suất hoán tỉnh hoán tỉnh thể SSR giới hạn<SummonPurple:Castor> sẽ tăng lên.\n\n·Trong sự kiện hoán tỉnh có thời hạn này, trừ các quy tắc đặc biệt như tăng xác suất và có mức bảo đảm, tất cả hoán tỉnh thể hoặc bánh xe sẽ sử dụng xác suất cơ bản, cụ thể theo quy tắc hướng dẫn.\n\n<Title:【Điều chỉnh cân bằng】>\n·Do đặc điểm gameplay, để đảm bảo sự thú vị và công bằng của trò chơi, có thể có các điều chỉnh cân bằng nhằm giảm bớt hoặc tăng cường hiệu ứng của hoán tỉnh thể và bánh xe.\n·Khi xảy ra giảm bớt, trò chơi sẽ kích hoạt tính năng hồi phục có thời hạn để cho hoán tỉnh thể và bánh xe có cơ hội tái phân bổ tài nguyên.\n·Xin hãy chắc chắn rằng bạn đã hiểu và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_141456_LongDesc2 = {
    Text = "<Title:[SSR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật giới hạn thời gian 【<SummonPurple:Cánh Tối Đen>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR thông qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonPurple:Cas-tơ-lơ> trong đợt này.\n· Nếu liên tiếp 2 lần thức tỉnh nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất nâng cao trong đợt này, thì lần thức tỉnh tiếp theo nhận được nhân vật SSR chắc chắn sẽ là nhân vật có xác suất nâng cao trong đợt này.{s1}\n· Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải là UP trong đợt này.{s3}\n\n<Title:[SR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật 【<SummonPurple:Cánh Tối Đen>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong đợt thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn qua bảo đảm, xác suất nhận được vật phẩm SR qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n· Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ cùng lúc nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ cùng lúc nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Dù bằng cách nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, quà tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh dư thừa thông qua các phương thức tùy chọn (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, horizon nguyên mẫu, v.v.) và phương thức ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên, v.v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về 【thức tỉnh hoạt động nhân vật】, trong bất kỳ 【thức tỉnh hoạt động nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
