  Summon_55879_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_55879_LongDesc1 = {
    Text = "[<SummonOrange:Hy vọng tinh khiết>] sự kiện Vòng mệnh có giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh UP giới hạn thời gian <SummonOrange:Vượt qua nỗi đau>.\n· Trong thời gian sự kiện, xác suất thức tỉnh vòng mệnh SSR giới hạn <SummonOrange:Vượt qua nỗi đau> sẽ được nâng cao.\n· Sau khi sự kiện kết thúc, vòng mệnh SSR giới hạn <SummonOrange:Vượt qua nỗi đau> vẫn sẽ xuất hiện trong sự kiện vòng mệnh có giới hạn thời gian sau lần UP đầu tiên trong khoảng từ 3 - 9 tháng, cho đến khoảng một năm sau sẽ chuyển vào sự kiện thức tỉnh vòng mệnh thường trực [Pha Quay].\n· Trong sự kiện thức tỉnh có giới hạn thời gian này, ngoài việc có xác suất nâng cao, bảo đảm và các quy tắc đặc biệt khác, tất cả các thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định đã nêu.\n· Đề xuất thức tỉnh hàng ngày: Trong sự kiện thức tỉnh có giới hạn thời gian này, Người Giữ Gìn có thể thức tỉnh một lần mỗi ngày với ưu đãi 60 nguồn lỏng và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n· Do cách chơi của trò chơi đặc biệt, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, có thể có điều chỉnh cân bằng trong việc giảm sức mạnh hoặc tăng sức mạnh của các thể thức tỉnh và hiệu ứng trong vòng mệnh.\n· Khi có sự giảm sức mạnh, trò chơi sẽ mở chức năng hồi tố có giới hạn thời gian để cho phép việc phát triển hoặc thức tỉnh của các thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n· Xin hãy chắc chắn rằng bạn đã hiểu và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_55879_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện vòng mệnh giới hạn【<SummonOrange:Hy vọng tinh khiết>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần hoán tỉnh chắc chắn sẽ nhận được vòng mệnh SSR thông qua bảo đảm.\n·Khi nhận được vòng mệnh SSR thông qua hoán tỉnh, có 50.00% xác suất là vòng mệnh SSR <SummonOrange:Vượt qua nỗi đau> của kỳ này.\n·Nếu vòng mệnh SSR nhận được từ lần hoán tỉnh trước không phải là vòng mệnh có xác suất nâng cao trong kỳ này, thì vòng mệnh SSR nhận được từ lần hoán tỉnh tiếp theo chắc chắn sẽ là vòng mệnh có xác suất nâng cao trong kỳ này.\n\n<Title:【SR vật phẩm】>\nTrong sự kiện hoán tỉnh vòng mệnh【<SummonOrange:Hy vọng tinh khiết>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần hoán tỉnh này đều là vòng mệnh.\n·Tối đa 5 lần hoán tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n·Khi nhận được vòng mệnh SSR thông qua hoán tỉnh, sẽ nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n·Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn hoán tỉnh, đổi tại cửa hàng, hệ thống tặng, v. v.) từ lần thứ 2~16 nhận được cùng một vòng mệnh SSR, mỗi lần sẽ tự động nâng cấp cấp độ xếp chồng và nhận được 「Căn nguyên lắng đọng」× 50; từ lần thứ 17 trở đi, sẽ được chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 1,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 2,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000. Tuy nhiên khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm Sách luân chuyển, Lõi hồi tố mệnh đồ, v. v.) cũng như phương thức ngẫu nhiên(bao gồm Định mệnh định hình·Thiên vong, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n·Lần hoán tỉnh này thuộc về【Sự kiện Vòng mệnh Thức tỉnh】, trong bất kỳ lần【Sự kiện Vòng mệnh Thức tỉnh】nào, số lần hoán tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê riêng biệt với số lần hoán tỉnh bảo đảm của các loại hoán tỉnh khác.\n"
  },
