  Summon_55884_Desc = {
    Text = "Mỗi <SummonBlue:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_55884_LongDesc1 = {
    Text = "[<SummonBlue:Khoảnh khắc chính vị>] sự kiện thức tỉnh hoạt động nhân vật có giới hạn thời gian đã bắt đầu. Trong thời gian sự kiện, Người Giữ Gìn có thể đánh thức nhân vật UP sự kiện giới hạn <SummonBlue:tulô>.\n· Trong thời gian sự kiện, xác suất nhận được thể thức tỉnh SSR giới hạn <SummonBlue:tulô> sẽ được tăng cường.\n· Sau khi sự kiện kết thúc, thể thức tỉnh SSR giới hạn <SummonBlue:tulô> vẫn sẽ xuất hiện trong sự kiện thức tỉnh nhân vật có giới hạn thời gian từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào thức tỉnh nhân vật thường trú trong [Cõi nghiên cứu].\n· Trong sự kiện thức tỉnh có giới hạn thời gian này, trừ các quy tắc đặc biệt như tăng xác suất, bảo đảm, tất cả các thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo hướng dẫn quy tắc.\n· Khuyến nghị thức tỉnh hàng ngày: Trong sự kiện thức tỉnh có giới hạn thời gian này, Người Giữ Gìn có thể thức tỉnh một lần với 60 nguồn lỏng mỗi ngày, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n· Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo niềm vui và tính công bằng, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh và vòng mệnh.\n· Khi xảy ra việc giảm, trò chơi sẽ mở chức năng hồi phục có giới hạn thời gian để cho phép việc phát triển hoặc thức tỉnh của thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n· Xin hãy đảm bảo rằng bạn hiểu và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_55884_LongDesc2 = {
    Text = "<Title:[SSR vật phẩm]>\n·Trong hoạt động nhân vật giới hạn thời gian 【<SummonBlue:Khoảnh khắc chính vị>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR thông qua bảo đảm.\n·Khi nhận được thể thức tỉnh SSR qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonBlue:tulô> trong đợt này.\n·Nếu liên tiếp 2 lần thức tỉnh không nhận được thể thức tỉnh nhân vật có xác suất tăng trong đợt này, lần thức tỉnh tiếp theo chắc chắn sẽ nhận được nhân vật có xác suất tăng trong đợt này.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải trong đợt UP này.{s3}\n\n<Title:[SR vật phẩm]>\n·Trong hoạt động thức tỉnh nhân vật 【<SummonBlue:Khoảnh khắc chính vị>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n·Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n·Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n·Dù nhận được bằng bất kỳ cách nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, quà tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và 「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Nhưng khi nhận được thể thức tỉnh hoặc mảnh thừa của thể thức tỉnh bằng cách chọn ngẫu nhiên (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, Horizon Nguyên mẫu, v.v.) và cách ngẫu nhiên (bao gồm bắt giữ nguyên chất·Bài Quên, v.v.) thì sẽ không chuyển đổi căn nguyên lắng đọng.\n·Lần thức tỉnh này thuộc về【thức tỉnh hoạt động nhân vật】, trong bất kỳ【thức tỉnh hoạt động nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
