  Summon_55890_Title = {
    Text = "Gửi hồn"
  },
  Summon_65250_Desc = {
    Text = "Mỗi <SummonBlue:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_65250_LongDesc1 = {
    Text = "[<SummonBlue:hố sâu giáng sinh>] Hoạt động nhân vật hạn chế để thức tỉnh đã mở cửa. Trong thời gian hoạt động, Người Giữ Gìn có thể thức tỉnh nhân vật UP hạn chế <SummonBlue:Miriam>. \n·Trong thời gian hoạt động, xác suất thức tỉnh nhân vật SSR hạn chế <SummonBlue:Miriam> sẽ được tăng lên. \n·Sau khi hoạt động kết thúc, nhân vật SSR hạn chế <SummonBlue:Miriam> vẫn sẽ xuất hiện trong các hoạt động hạn chế để thức tỉnh nhân vật sau 3 đến 9 tháng kể từ lần UP đầu tiên, cho đến khoảng một năm sau khi vào [giới vực nghiên cứu] để thức tỉnh nhân vật thường trú. \n·Trong lần thức tỉnh hạn chế này, ngoài các quy tắc đặc biệt như tăng xác suất thức tỉnh và bảo đảm, tất cả thân thể được đánh thức hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo Quy tắc giải thích. \n·Thức tỉnh khuyến mãi hàng ngày: Trong lần thức tỉnh hạn chế này, Người Giữ Gìn có thể thức tỉnh một lần với giá ưu đãi 60 nguồn lỏng mỗi ngày và nhận thêm 60 bạc tâm. \n\n<Title:[điều chỉnh cân bằng]>\n·Do cách chơi trò chơi đặc biệt, từ góc độ đảm bảo niềm vui và công bằng của trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng bằng cách giảm hoặc tăng cường hiệu ứng của thân thể được đánh thức hoặc vòng mệnh. \n·Khi bị giảm sức mạnh, trò chơi sẽ mở chức năng hồi tố hạn chế để người chơi có cơ hội tái bố trí tài nguyên cho thân thể được đánh thức hoặc vòng mệnh. \n·Hãy chắc chắn hiểu và chấp nhận điểm này trước khi tiến hành đầu tư tài nguyên. \n\n"
  },
  Summon_65250_LongDesc2 = {
    Text = "<Title:[Vật phẩm SSR]>\nTrong hoạt động thức tỉnh nhân vật có thời hạn【<SummonBlue:Sự giáng sinh của vực thẳm>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn có thể nhận được thể thức tỉnh SSR thông qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonBlue:Miriam> trong đợt này.\n· Nếu nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất tăng cường trong 2 lần thức tỉnh liên tiếp, thì lần thức tỉnh tiếp theo sẽ chắc chắn nhận được nhân vật có xác suất tăng cường trong đợt này.{s1}\n· Hiện tại đã liên tiếp nhận được {s2} lần nhân vật không phải UP trong đợt này.{s3}\n\n<Title:[Vật phẩm SR]>\nTrong hoạt động thức tỉnh nhân vật【<SummonBlue:Sự giáng sinh của vực thẳm>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn có thể nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n· Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể bằng cách nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, quà tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và 「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR có giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh tràn ra qua các phương thức tùy chọn (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, cảnh quan nguyên mẫu, v.v.) và phương thức ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về【Thức tỉnh hoạt động nhân vật】, trong bất kỳ【Thức tỉnh hoạt động nhân vật】nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
