  Summon_66905_Desc = {
    Text = "Mỗi <SummonRed:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_66905_LongDesc1 = {
    Text = "[<SummonRed:mắt thấy mẹ>] Sự kiện thức tỉnh nhân vật có giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh nhân vật UP có giới hạn thời gian <SummonRed:Thái Di Sơ>.\n· Trong thời gian sự kiện, xác suất nhận được thân thể được đánh thức SSR giới hạn <SummonRed:Thái Di Sơ> sẽ tăng lên.\n· Sau khi sự kiện kết thúc, thân thể được đánh thức SSR giới hạn <SummonRed:Thái Di Sơ> vẫn sẽ xuất hiện trong sự kiện thức tỉnh nhân vật có giới hạn thời gian từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào thức tỉnh nhân vật thường trú trong [giới vực nghiên cứu].\n· Trong sự kiện thức tỉnh có giới hạn thời gian này, ngoài việc kích hoạt xác suất tăng lên, bảo đảm và các quy tắc đặc biệt khác, tất cả thân thể được đánh thức hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy tắc đã được giải thích.\n· Đề xuất thức tỉnh hàng ngày: Trong sự kiện thức tỉnh có giới hạn thời gian này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với 60 nguồn lỏng ưu đãi, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n· Do tính chất đặc biệt của lối chơi, để đảm bảo sự vui vẻ và công bằng trong trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thân thể được đánh thức và vòng mệnh.\n· Khi có sự giảm thiểu, trò chơi sẽ mở chức năng quay ngược có giới hạn thời gian để cho phép việc phát triển hoặc thức tỉnh của thân thể được đánh thức, vòng mệnh có cơ hội tái phân bổ tài nguyên.\n· Vui lòng đảm bảo rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_66905_LongDesc2 = {
    Text = "<Title:【Vật phẩm SSR】>\nTrong gọi thức giới hạn nhân vật【<SummonRed:Gặp lại mẹ>】, tỷ lệ cơ bản nhận được vật phẩm SSR là 3.03%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 5.02%. Vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần gọi thức chắc chắn nhận được thể thức tỉnh SSR thông qua bảo đáy.\n·Khi nhận được thể thức tỉnh SSR thông qua gọi thức, có 33.33% xác suất là thể thức tỉnh SSR UP kỳ này <SummonRed:Tethys>.\n·Nếu 2 lần gọi thức liên tiếp nhận được thể thức tỉnh SSR không phải nhân vật tăng xác suất kỳ này, thì lần gọi thức tiếp theo nhận được nhân vật SSR chắc chắn là nhân vật tăng xác suất kỳ này.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải UP kỳ này.{s3}\n\n<Title:【Vật phẩm SR】>\nTrong gọi thức nhân vật hoạt động【<SummonRed:Gặp lại mẹ>】, tỷ lệ cơ bản nhận được vật phẩm SR là 15.85%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 25.00%. Vật phẩm SR trong lần gọi thức này đều là Mệnh Luân.\n·Tối đa 5 lần gọi thức chắc chắn nhận được vật phẩm SR trở lên thông qua bảo đáy, xác suất nhận được vật phẩm SR thông qua bảo đáy là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Thuyết minh đặc biệt】>\n·Khi gọi thức nhận được Mệnh Luân SR, sẽ đồng thời nhận được 5 Căn Nguyên Trầm Tích làm sản phẩm phụ; khi nhận được Mệnh Luân R, sẽ đồng thời nhận được 1 Căn Nguyên Trầm Tích làm sản phẩm phụ.\n·Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn gọi thức, đổi cửa hàng, hệ thống tặng, v.v.) lần thứ 2~16 nhận được cùng thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ thể thức tỉnh tương ứng và 50 Căn Nguyên Trầm Tích; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành \"Mảnh Hồi Tố Linh Hồn\" × 1 và \"Căn Nguyên Trầm Tích\" × 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành \"Mảnh Hồi Tố Linh Hồn\" × 2 và \"Căn Nguyên Trầm Tích\" × 250. Tuy nhiên khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh dư thừa thông qua phương thức tự chọn (bao gồm Nguyên Chất Lạc Viên, Lõi Hồi Tố Linh Hồn, Nguyên Mẫu Thị Giới, v.v.) cũng như phương thức ngẫu nhiên (bao gồm Nguyên Chất Bắt Giữ·Thiên Vong Quên, v.v.), sẽ không chuyển đổi Căn Nguyên Trầm Tích.\n·Lần gọi thức này thuộc【Gọi thức hoạt động nhân vật】, trong bất kỳ【Gọi thức hoạt động nhân vật】nào, số lần gọi thức bảo đáy sẽ được tích lũy chung, và được thống kê độc lập với số lần gọi thức bảo đáy của các loại gọi thức khác.\n\n"
  },
