  Summon_66915_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_66915_LongDesc1 = {
    Text = "[<SummonOrange:Xâm phạm Thánh Ca>] Sự kiện Vòng mệnh Thức tỉnh có thời gian giới hạn đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh UP giới hạn thời gian <SummonOrange:Khúc cầu hồn vĩnh cửu>.\n·Trong thời gian sự kiện, xác suất thức tỉnh vòng mệnh SSR giới hạn <SummonOrange:Khúc cầu hồn vĩnh cửu> sẽ được tăng cường.\n·Sau khi sự kiện kết thúc, vòng mệnh SSR giới hạn <SummonOrange:Khúc cầu hồn vĩnh cửu> vẫn sẽ xuất hiện trong các sự kiện Vòng mệnh có thời gian giới hạn từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào <Pha Quay> Thức tỉnh vòng mệnh thường trực.\n·Trong lần thức tỉnh sự kiện có thời gian giới hạn này, ngoài các quy tắc đặc biệt như tăng xác suất và bảo đảm, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định.\n·Khuyến nghị thức tỉnh hàng ngày: Trong lần thức tỉnh sự kiện có thời gian giới hạn này, Người Giữ Gìn có thể thức tỉnh một lần với 60 nguồn lỏng và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo sự thú vị và công bằng, trò chơi có thể thực hiện các điều chỉnh cân bằng để giảm hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự giảm sức mạnh, trò chơi sẽ mở chức năng hồi tưởng có thời gian giới hạn để cho phép tái phân bổ tài nguyên cho việc nuôi dưỡng hoặc thức tỉnh thể thức tỉnh và vòng mệnh.\n·Xin hãy chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_66915_LongDesc2 = {
    Text = "<Title:【SSR Vật phẩm】>\nTrong hoạt động thức tỉnh vòng mệnh giới hạn【<SummonOrange:Xâm phạm Thánh Ca>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được vòng mệnh SSR thông qua bảo đảm.\n· Khi nhận được vòng mệnh SSR thông qua thức tỉnh, có 50.00% xác suất là vòng mệnh SSR【<SummonOrange:Khúc cầu hồn vĩnh cửu>】đang được tăng xác suất trong kỳ này.\n· Nếu vòng mệnh SSR nhận được lần thức tỉnh trước không phải là vòng mệnh tăng xác suất trong kỳ này, thì vòng mệnh SSR nhận được lần thức tỉnh tiếp theo chắc chắn sẽ là vòng mệnh tăng xác suất trong kỳ này.\n\n<Title:【SR Vật phẩm】>\nTrong hoạt động thức tỉnh vòng mệnh【<SummonOrange:Xâm phạm Thánh Ca>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n· Khi nhận được vòng mệnh SSR, sẽ cùng lúc nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ cùng lúc nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ cùng lúc nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, hệ thống tặng, v. v.) từ lần thứ 2~16 nhận được cùng một vòng mệnh SSR, mỗi lần sẽ tự động nâng cấp cấp độ chồng vị và nhận được 「căn nguyên lắng đọng」× 50; từ lần thứ 17 trở đi, sẽ chuyển đổi thành 「mảnh hồi tố mệnh đồ」× 1,「căn nguyên lắng đọng」× 50,「phiếu vàng tường vi」× 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành 「mảnh hồi tố mệnh đồ」× 2,「căn nguyên lắng đọng」× 50,「phiếu vàng tường vi」× 20000. Nhưng khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm sách luân chuyển, lõi hồi tố mệnh đồ, v. v.) cũng như phương thức ngẫu nhiên(bao gồm định cách túc mệnh·thiên vong, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về【Hoán tỉnh vòng mệnh】, trong bất kỳ【Hoán tỉnh vòng mệnh】nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n"
  },
