  Summon_66921_ShortDesc = {
    Text = "Chắc chắn sẽ nhận được thân thể được đánh thức <SummonPurple:siêu việt> giới vực"
  },
  Summon_66921_Title = {
    Text = "Gửi hồn"
  },
  Summon_66922_Desc = {
    Text = "Mỗi <SummonRed:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_66922_LongDesc1 = {
    Text = "[<SummonRed:Cốc cao của bữa tiệc thịnh soạn>] Thức tỉnh hoạt động nhân vật có giới hạn thời gian đã được mở. Trong thời gian hoạt động, Người Giữ Gìn có thể thức tỉnh nhân vật UP có giới hạn thời gian <SummonRed:Sorrel>.\n·Trong thời gian hoạt động, xác suất thức tỉnh của thể thức tỉnh SSR giới hạn <SummonRed:Sorrel> sẽ được nâng cao.\n·Sau khi kết thúc hoạt động, thể thức tỉnh SSR giới hạn <SummonRed:Sorrel> vẫn sẽ xuất hiện trong hoạt động thức tỉnh nhân vật có giới hạn thời gian từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào thức tỉnh nhân vật thường trú trong [giới vực nghiên cứu].\n·Trong lần thức tỉnh hoạt động có giới hạn này, ngoài việc tăng xác suất kích hoạt, bảo đảm và các quy tắc đặc biệt khác, tất cả các thể thức tỉnh hoặc vòng mệnh sẽ sử dụng xác suất cơ bản, cụ thể theo quy định.\n·Khuyến nghị thức tỉnh hàng ngày: Trong lần thức tỉnh hoạt động có giới hạn này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với 60 nguồn lỏng với ưu đãi và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo niềm vui và tính công bằng, trò chơi có thể thực hiện điều chỉnh cân bằng làm yếu hoặc tăng cường hiệu ứng của thể thức tỉnh, vòng mệnh.\n·Khi xảy ra việc làm yếu, trò chơi sẽ mở chức năng hồi cứu có giới hạn thời gian để cho phép thể thức tỉnh, vòng mệnh có cơ hội tái phân bổ tài nguyên trong quá trình phát triển hoặc thức tỉnh.\n·Xin vui lòng chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_66922_LongDesc2 = {
    Text = "<Title:【SSR Vật phẩm】>\nTrong [<SummonRed:Yến Tiệc Cao Sang>] sự kiện triệu hồi nhân vật giới hạn, tỉ lệ cơ bản để nhận vật phẩm SSR là 3.03%, tỉ lệ tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa sau 30 lần triệu hồi chắc chắn sẽ nhận được thức tỉnh thể SSR thông qua cơ chế bảo đảm.\n· Khi nhận được thức tỉnh thể SSR qua triệu hồi, có 33.33% cơ hội nhận thức tỉnh thể SSR có tăng tỉ lệ của kỳ này <SummonRed:Sorel>.\n· Nếu liên tục 2 lần triệu hồi nhận thức tỉnh thể SSR không phải là nhân vật có tăng tỉ lệ của kỳ này, thì lần triệu hồi tiếp theo nhận thức tỉnh thể SSR chắc chắn sẽ là nhân vật có tăng tỉ lệ của kỳ này.{s1}\n· Hiện tại đã liên tục {s2} lần nhận nhân vật không phải là UP của kỳ này.{s3}\n\n<Title:【SR Vật phẩm】>\nTrong [<SummonRed:Yến Tiệc Cao Sang>] triệu hồi sự kiện nhân vật, tỉ lệ cơ bản để nhận vật phẩm SR là 15.85%, tỉ lệ tổng hợp(bao gồm bảo đảm) là 25.00%. Vật phẩm SR trong triệu hồi này đều là Mệnh Luân.\n· Tối đa 5 lần triệu hồi chắc chắn sẽ nhận được vật phẩm SR trở lên thông qua cơ chế bảo đảm, tỉ lệ nhận được vật phẩm SR thông qua bảo đảm là 96.97%, tỉ lệ nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Chú thích đặc biệt】>\n· Khi nhận được Mệnh Luân SR qua triệu hồi, sẽ đồng thời nhận được 5 Nguyên Bản Trầm Tích như một sản phẩm phụ; khi nhận được Mệnh Luân R, sẽ đồng thời nhận được 1 Nguyên Bản Trầm Tích.\n· Bất kể thông qua hình thức nào(bao gồm nhưng không giới hạn bởi triệu hồi, đổi tại cửa hàng, quà tặng từ hệ thống v. v.), từ lần thứ 2 đến lần thứ 16 nhận được cùng thức tỉnh thể SSR, mỗi lần sẽ được chuyển đổi thành 1 mảnh của thức tỉnh thể tương ứng và 50 Nguyên Bản Trầm Tích; từ lần thứ 17 trở đi, thức tỉnh thể SSR không giới hạn sẽ được chuyển đổi thành \"Mảnh hồi tưởng linh hồn\" × 1 và\"Nguyên Bản Trầm Tích\" × 150, thức tỉnh thể SSR giới hạn sẽ được chuyển đổi thành \"Mảnh hồi tưởng linh hồn\" × 2 và\"Nguyên Bản Trầm Tích\" × 250. Tuy nhiên, khi nhận thức tỉnh thể hoặc phần thừa của thức tỉnh thể thông qua phương thức tùy chọn(bao gồm Công Viên Nguyên Chất, Lõi Hồi Tưởng Linh Hồn, Góc Nhìn Nguyên Mẫu v. v.) hoặc phương thức ngẫu nhiên(bao gồm Nguyên Chất Bắt Giữ·Phiên Lãng Quên v. v.), sẽ không chuyển đổi thành Nguyên Bản Trầm Tích.\n· Triệu hồi lần này thuộc [Triệu hồi sự kiện nhân vật], tất cả lần triệu hồi bảo đảm trong bất kỳ [Triệu hồi sự kiện nhân vật] nào sẽ được tích lũy chung, và được thống kê độc lập với các loại triệu hồi khác.\n\n"
  },
