  Summon_66928_Desc = {
    Text = "Mỗi <SummonBlue:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_66928_LongDesc1 = {
    Text = "[<SummonBlue:Sự Khát Vọng Bị Giam Giữ Sâu Sắc>] Sự kiện thức tỉnh nhân vật có giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể từ đó thức tỉnh nhân vật UP có giới hạn thời gian <SummonBlue:Muphí>.\n· Trong thời gian sự kiện, xác suất thức tỉnh của thể thức tỉnh SSR giới hạn <SummonBlue:Muphí> sẽ được tăng cường.\n· Sau khi sự kiện kết thúc, thể thức tỉnh SSR giới hạn <SummonBlue:Muphí> vẫn sẽ xuất hiện trong sự kiện thức tỉnh nhân vật có giới hạn thời gian từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào thức tỉnh nhân vật thường trú trong [giới vực nghiên cứu].\n· Trong sự kiện thức tỉnh có giới hạn thời gian này, ngoài việc kích hoạt xác suất tăng cường, bảo đảm và các quy tắc đặc biệt khác, tất cả thể thức tỉnh hoặc vòng mệnh sẽ sử dụng xác suất cơ bản, cụ thể theo quy định đã được mô tả.\n· Khuyến nghị thức tỉnh hàng ngày: Trong sự kiện thức tỉnh có giới hạn thời gian này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với 60 nguồn lỏng ưu đãi, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều Chỉnh Cân Bằng]>\n· Do tính chất đặc biệt của lối chơi, nhằm đảm bảo sự vui vẻ và công bằng của trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng bằng cách giảm hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh.\n· Khi xảy ra giảm sức mạnh, trò chơi sẽ mở chức năng hồi tố có giới hạn thời gian để cho phép thể thức tỉnh và vòng mệnh có cơ hội tái bố trí tài nguyên.\n· Vui lòng đảm bảo rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_66928_LongDesc2 = {
    Text = "<Title:[Vật phẩm SSR]>\nTrong sự kiện hoạt động nhân vật giới hạn 【<SummonBlue:Sự Khát Vọng Bị Giam Giữ Sâu Sắc>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả các vật phẩm SSR nhận được đều là thể thức tỉnh, và tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR thông qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR thông qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonBlue:Muphí> trong đợt này.\n· Nếu liên tiếp 2 lần thức tỉnh mà nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất nâng cao trong đợt này, thì lần thức tỉnh tiếp theo sẽ chắc chắn nhận được nhân vật có xác suất nâng cao trong đợt này.{s1}\n· Hiện tại đã liên tiếp nhận được {s2} lần không phải nhân vật UP trong đợt này.{s3}\n\n<Title:[Vật phẩm SR]>\nTrong sự kiện hoạt động nhân vật 【<SummonBlue:Sự Khát Vọng Bị Giam Giữ Sâu Sắc>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả các vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh sẽ chắc chắn nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n· Khi nhận được vòng mệnh SR thông qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, quà tặng từ hệ thống, v.v.) trong lần 2~16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tưởng linh hồn」× 1 và「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR có giới hạn sẽ chuyển đổi thành「Mảnh hồi tưởng linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh bị tràn thông qua phương thức tùy chọn (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, horizon nguyên mẫu, v.v.) và phương thức ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về 【Thức tỉnh hoạt động nhân vật】, trong bất kỳ 【Thức tỉnh hoạt động nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung và độc lập thống kê với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
