  Summon_66941_ShortDesc = {
    Text = "Chắc chắn nhận được thân thể được đánh thức là <SummonBlue:biển sâu> lãnh vực"
  },
  Summon_66941_Title = {
    Text = "Khoảnh khắc chính vị"
  },
  Summon_66942_Desc = {
    Text = "Mỗi <SummonPurple:5> lần thức tỉnh bắt buộc có đối tượng cấp SR hoặc cao hơn"
  },
  Summon_66942_LongDesc1 = {
    Text = "[<SummonPurple:Chúa tể của gai nhọn>] Sự kiện hoạt động nhân vật giới hạn đã bắt đầu. Trong thời gian sự kiện, Người Giữ Gìn có thể đánh thức nhân vật UP giới hạn sự kiện <SummonPurple:Vanda>.\n·Trong thời gian sự kiện, xác suất thức tỉnh của thể thức tỉnh SSR giới hạn <SummonPurple:Vanda> sẽ được tăng cường.\n·Sau khi sự kiện kết thúc, thể thức tỉnh SSR giới hạn <SummonPurple:Vanda> vẫn sẽ xuất hiện trong sự kiện hoạt động nhân vật giới hạn từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào thức tỉnh nhân vật thường trú trong [giới vực nghiên cứu].\n·Trong lần thức tỉnh sự kiện giới hạn này, ngoài việc kích hoạt xác suất tăng cường, bảo đảm và các quy tắc đặc biệt khác, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định được mô tả.\n·Đề xuất thức tỉnh hàng ngày: Trong lần thức tỉnh sự kiện giới hạn này, Người Giữ Gìn có thể thức tỉnh một lần với 60 nguồn lỏng và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo sự thú vị và công bằng, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự giảm nhẹ xảy ra, trò chơi sẽ mở chức năng hồi tưởng giới hạn để cho phép thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n·Xin vui lòng đầu tư tài nguyên chỉ khi bạn đã biết và chấp nhận điều này.\n\n"
  },
  Summon_66942_LongDesc2 = {
    Text = "<Title:[SSR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật giới hạn [<SummonPurple:Chúa tể của gai nhọn>], xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonPurple:Vanda> trong đợt này.\n· Nếu 2 lần thức tỉnh liên tiếp nhận được thể thức tỉnh SSR không phải là nhân vật được nâng cao xác suất trong đợt này, thì lần thức tỉnh tiếp theo chắc chắn sẽ nhận được nhân vật nâng cao xác suất trong đợt này. {s1}\n· Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải là UP trong đợt này. {s3}\n\n<Title:[SR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật [<SummonPurple:Chúa tể của gai nhọn>], xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn qua bảo đảm, xác suất nhận được vật phẩm SR qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n· Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể bằng cách nào(bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, quà tặng từ hệ thống, v. v.), từ lần thứ 2 đến lần thứ 16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng với thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành \"Mảnh hồi tố linh hồn\" × 1 và \"Căn nguyên lắng đọng\" × 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành \"Mảnh hồi tố linh hồn\" × 2 và\"Căn nguyên lắng đọng\" × 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh tràn qua các cách lựa chọn(bao gồm Khu vui chơi nguyên chất, Lõi Trở Lại Linh Hồn, Horizon Nguyên mẫu, v. v.) và cách ngẫu nhiên(bao gồm Bắt giữ nguyên chất·Bài Quên, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về [thức tỉnh hoạt động nhân vật], trong bất kỳ [thức tỉnh hoạt động nhân vật] nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác. \n\n"
  },
