  Summon_66952_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh chắc chắn nhận được đối tượng SR hoặc cao hơn"
  },
  Summon_66952_LongDesc1 = {
    Text = "[<SummonOrange:Người chơi số phận>] hoạt động nhân vật giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể đánh thức nhân vật UP hoạt động giới hạn <SummonOrange:Lắc>.\n·Trong thời gian sự kiện, xác suất nhận được thể thức tỉnh SSR giới hạn <SummonOrange:Lắc> sẽ được tăng lên.\n·Sau khi sự kiện kết thúc, thể thức tỉnh SSR giới hạn <SummonOrange:Lắc> vẫn sẽ xuất hiện trong hoạt động nhân vật giới hạn thời gian từ 3 đến 9 tháng sau lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào hoạt động thức tỉnh nhân vật thường trú [giới vực nghiên cứu].\n·Trong hoạt động thức tỉnh giới hạn thời gian này, ngoài các quy tắc đặc biệt như tăng xác suất, bảo đảm, v.v., tất cả các thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định đã nêu.\n·Đề xuất thức tỉnh hàng ngày: Trong hoạt động thức tỉnh giới hạn thời gian này, Người Giữ Gìn có thể thức tỉnh một lần với ưu đãi 60 nguồn lỏng mỗi ngày, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi đặc biệt của trò chơi, để đảm bảo sự vui vẻ và công bằng trong trò chơi, có thể sẽ có điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự giảm, trò chơi sẽ mở chức năng hồi tưởng giới hạn thời gian để cho phép có cơ hội tái phân bổ tài nguyên cho việc phát triển hoặc thức tỉnh của thể thức tỉnh và vòng mệnh.\n·Xin hãy chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_66952_LongDesc2 = {
    Text = "<Title:[SSR vật phẩm]>\nTrong hoạt động nhân vật giới hạn 【<SummonOrange:Người chơi số phận>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR thông qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR thông qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonOrange:Lắc> của đợt này.\n· Nếu trong 2 lần thức tỉnh liên tiếp nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất tăng cường trong đợt này, lần thức tỉnh tiếp theo nhận được thể thức tỉnh SSR chắc chắn sẽ là nhân vật có xác suất tăng cường trong đợt này.{s1}\n· Hiện tại đã liên tiếp nhận được {s2} lần nhân vật không phải là nhân vật có xác suất tăng cường trong đợt này.{s3}\n\n<Title:[SR vật phẩm]>\nTrong hoạt động thức tỉnh nhân vật 【<SummonOrange:Người chơi số phận>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n· Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua cách nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, quà tặng từ hệ thống, v.v.), từ lần thứ 2 đến lần thứ 16 nhận được thể thức tỉnh SSR giống nhau, mỗi lần sẽ chuyển đổi thành 1 mảnh tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Phân mảnh hồi tố linh hồn」× 1 và「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR có giới hạn sẽ chuyển đổi thành「Phân mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh thể thức tỉnh thừa thông qua các cách tùy chọn (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, chân trời nguyên mẫu, v.v.) và cách ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về 【thức tỉnh hoạt động nhân vật】, trong bất kỳ 【thức tỉnh hoạt động nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung và thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
