  Summon_66958_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_66958_LongDesc1 = {
    Text = "[<SummonOrange:Sự Vinh Dự Hư Ảo>] Sự kiện Vòng mệnh Thức tỉnh giới hạn đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh UP hoạt động giới hạn <SummonOrange:Chào đời bí mật>.\n·Trong thời gian sự kiện, xác suất thức tỉnh vòng mệnh SSR giới hạn <SummonOrange:Chào đời bí mật> sẽ được tăng lên.\n·Sau khi sự kiện kết thúc, vòng mệnh SSR giới hạn <SummonOrange:Chào đời bí mật> vẫn sẽ xuất hiện trong sự kiện thức tỉnh vòng mệnh giới hạn trong 3 - 9 tháng sau lần UP đầu tiên, cho đến khi khoảng một năm sau sẽ vào giai đoạn thức tỉnh vòng mệnh thường trực <Pha Quay>.\n·Trong sự kiện thức tỉnh giới hạn lần này, ngoài việc kích hoạt xác suất tăng, bảo đảm và các quy tắc đặc biệt khác, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định đã nêu.\n·Khuyến nghị thức tỉnh hàng ngày: Trong sự kiện thức tỉnh giới hạn lần này, Người Giữ Gìn có thể thức tỉnh một lần với 60 nguồn lỏng với ưu đãi, và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều Chỉnh Cân Bằng]>\n·Do cách chơi của trò chơi đặc biệt, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, có thể sẽ có điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự giảm sút, trò chơi sẽ mở chức năng hồi phục giới hạn để cho phép thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n·Vui lòng đảm bảo rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_66958_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong hoạt động vòng mệnh giới hạn [<SummonOrange:Sự Vinh Dự Hư Ảo>] khi thức tỉnh, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được vòng mệnh SSR thông qua bảo đảm.\n· Khi nhận được vòng mệnh SSR qua thức tỉnh, có 50.00% xác suất là vòng mệnh SSR <SummonOrange:Chào đời bí mật> của kỳ này.\n· Nếu vòng mệnh SSR nhận được ở lần thức tỉnh trước không phải là vòng mệnh có xác suất nâng cao của kỳ này, thì vòng mệnh SSR nhận được ở lần thức tỉnh tiếp theo chắc chắn sẽ là vòng mệnh có xác suất nâng cao của kỳ này.\n\n<Title:【SR vật phẩm】>\nTrong hoạt động thức tỉnh vòng mệnh [<SummonOrange:Sự Vinh Dự Hư Ảo>], xác suất cơ bản để thức tỉnh vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n· Khi nhận được vòng mệnh SSR qua thức tỉnh, sẽ đồng thời nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn hoán tỉnh, đổi tại cửa hàng, hệ thống tặng, v. v.) từ lần thứ 2~16 nhận được cùng một vòng mệnh SSR, mỗi lần sẽ tự động nâng cấp cấp độ xếp chồng và nhận được [Căn nguyên lắng đọng]× 50; từ lần thứ 17 trở đi, sẽ được chuyển đổi thành [Mảnh hồi tố mệnh đồ]× 1,[Căn nguyên lắng đọng]× 50,[Phiếu vàng tường vi]× 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành [Mảnh hồi tố mệnh đồ]× 2,[Căn nguyên lắng đọng]× 50,[Phiếu vàng tường vi]× 20000. Tuy nhiên khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm Sách luân chuyển, Lõi hồi tố mệnh đồ, v. v.) cũng như phương thức ngẫu nhiên(bao gồm Định mệnh định hình·Thiên vong, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về [Hoán tỉnh vòng mệnh], trong bất kỳ lần [Hoán tỉnh vòng mệnh] nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n"
  },
