  Summon_66965_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_66965_LongDesc1 = {
    Text = "[<SummonOrange:Lý do tồn tại>] sự kiện Vòng mệnh Thức tỉnh đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh UP giới hạn của sự kiện <SummonOrange:Từ bi dưỡng dục>.\n·Trong thời gian sự kiện, xác suất nhận được vòng mệnh SSR giới hạn <SummonOrange:Từ bi dưỡng dục> sẽ được nâng cao.\n·Sau khi sự kiện kết thúc, vòng mệnh SSR giới hạn <SummonOrange:Từ bi dưỡng dục> vẫn sẽ xuất hiện trong sự kiện Vòng mệnh Thức tỉnh giới hạn sau 3 - 9 tháng lần UP đầu tiên, cho đến khoảng một năm sau sẽ vào sự kiện Thức tỉnh Vòng Mệnh Thường Trực.\n·Trong sự kiện Thức tỉnh giới hạn này, ngoại trừ các quy tắc đặc biệt như nâng cao xác suất, bảo đảm, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định đã nêu.\n·Khuyến nghị thức tỉnh hàng ngày: Trong sự kiện Thức tỉnh giới hạn này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với 60 nguồn lỏng và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi đặc biệt của game, nhằm đảm bảo sự thú vị và công bằng của game, có thể sẽ có điều chỉnh cân bằng liên quan đến hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự giảm sức mạnh, game sẽ mở chức năng hồi phục có thời gian để cho phép người chơi có cơ hội tái phân bổ tài nguyên cho việc phát triển hoặc thức tỉnh thể thức tỉnh và vòng mệnh.\n·Xin hãy chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_66965_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện vòng mệnh giới hạn 【<SummonOrange:Lý do tồn tại>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần hoán tỉnh sẽ chắc chắn nhận được vòng mệnh SSR thông qua bảo đảm.\n· Khi nhận được vòng mệnh SSR thông qua hoán tỉnh, có 50.00% xác suất là vòng mệnh SSR <SummonOrange:Từ bi dưỡng dục> trong kỳ này.\n· Nếu vòng mệnh SSR nhận được từ lần hoán tỉnh trước không phải là vòng mệnh có xác suất nâng cao trong kỳ này, thì vòng mệnh SSR nhận được từ lần hoán tỉnh tiếp theo chắc chắn sẽ là vòng mệnh có xác suất nâng cao trong kỳ này.\n\n<Title:【SR vật phẩm】>\nTrong sự kiện hoán tỉnh vòng mệnh 【<SummonOrange:Lý do tồn tại>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần hoán tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần hoán tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n· Khi nhận được vòng mệnh SSR, sẽ đồng thời nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n·Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn hoán tỉnh, đổi cửa hàng, hệ thống tặng v. v.) lần thứ 2~16 nhận được cùng một SSR vòng mệnh, mỗi lần sẽ tự động nâng cấp cấp độ xếp chồng và nhận được 「Căn nguyên lắng đọng」× 50; từ lần thứ 17 trở đi, sẽ chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 1,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000, SSR vòng mệnh giới hạn sẽ chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 2,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000. Tuy nhiên khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm Sách luân chuyển, Lõi hồi tố mệnh đồ v. v.) cũng như phương thức ngẫu nhiên(bao gồm Định cách số mệnh·Thiên vong v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần hoán tỉnh này thuộc về 【Sự kiện Vòng mệnh Thức tỉnh】, trong bất kỳ 【Sự kiện Vòng mệnh Thức tỉnh】 nào, số lần hoán tỉnh bảo đảm sẽ được cộng dồn chung, và sẽ được thống kê độc lập với số lần hoán tỉnh bảo đảm của các loại hoán tỉnh khác.\n"
  },
