  Summon_77955_Desc = {
    Text = "Mỗi <SummonBlue:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_77955_LongDesc1 = {
    Text = "[<SummonBlue:Văn bản tạm thời>] Sự kiện thức tỉnh hoạt động nhân vật có thời gian giới hạn đã bắt đầu. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh nhân vật UP sự kiện giới hạn <SummonBlue:Thần Vương·Tulô>.\n·Trong thời gian sự kiện, xác suất thức tỉnh thể thức tỉnh SSR giới hạn <SummonBlue:Thần Vương·Tulô> sẽ được nâng cao.\n\n·Trong lần thức tỉnh sự kiện giới hạn này, ngoài việc kích hoạt xác suất nâng cao, bảo đảm và các quy tắc đặc biệt khác, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định được nêu.\n·Đề xuất thức tỉnh hàng ngày: Trong lần thức tỉnh sự kiện giới hạn này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với mức giá ưu đãi 60 nguồn lỏng và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi của trò chơi đặc biệt, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, trò chơi có thể thực hiện các điều chỉnh cân bằng để giảm hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi xảy ra việc giảm sức mạnh, trò chơi sẽ mở chức năng hồi tố có thời gian giới hạn để cho phép thể thức tỉnh và vòng mệnh có cơ hội tái phân bổ tài nguyên.\n·Xin hãy chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_77955_LongDesc2 = {
    Text = "<Title:【Vật phẩm SSR】>\nTrong gọi giới hạn thời gian nhân vật【<SummonBlue:Văn bản tạm thời>】, tỷ lệ cơ bản nhận được vật phẩm SSR là 3.03%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 5.02%. Vật phẩm SSR nhận được đều là Thể Thức Tỉnh, tối đa 30 lần gọi chắc chắn nhận được Thể Thức Tỉnh SSR thông qua bảo đáy.\n·Khi nhận được Thể Thức Tỉnh SSR thông qua gọi, có 33.33% xác suất là Thể Thức Tỉnh SSR UP kỳ này <SummonBlue:Thần Vương·Turu>.\n·Nếu 2 lần gọi liên tiếp nhận được Thể Thức Tỉnh SSR không phải nhân vật tăng xác suất kỳ này, thì lần gọi tiếp theo nhận được nhân vật SSR chắc chắn là nhân vật tăng xác suất kỳ này.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải UP kỳ này.{s3}\n\n<Title:【Vật phẩm SR】>\nTrong gọi nhân vật sự kiện【<SummonBlue:Văn bản tạm thời>】, tỷ lệ cơ bản nhận được vật phẩm SR là 15.85%, tỷ lệ tổng hợp (bao gồm bảo đáy) là 25.00%. Vật phẩm SR trong lần gọi này đều là Mệnh Luân.\n·Tối đa 5 lần gọi chắc chắn nhận được vật phẩm SR trở lên thông qua bảo đáy, xác suất nhận được vật phẩm SR thông qua bảo đáy là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Thuyết minh đặc biệt】>\n·Khi gọi nhận được Mệnh Luân SR, sẽ đồng thời nhận được 5 Ngưng Tụ Căn Nguyên làm sản phẩm phụ; khi nhận được Mệnh Luân R, sẽ đồng thời nhận được 1 Ngưng Tụ Căn Nguyên làm sản phẩm phụ.\n·Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn gọi, đổi cửa hàng, hệ thống tặng, v.v.) từ lần thứ 2~16 nhận được cùng Thể Thức Tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ Thể Thức Tỉnh tương ứng và 50 Ngưng Tụ Căn Nguyên; từ lần thứ 17 trở đi, Thể Thức Tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 1 và「Ngưng Tụ Căn Nguyên」× 150, Thể Thức Tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 2 và「Ngưng Tụ Căn Nguyên」× 250. Tuy nhiên khi nhận được Thể Thức Tỉnh hoặc mảnh vỡ Thể Thức Tỉnh dư thừa thông qua phương thức tự chọn (bao gồm Lạc Viên Nguyên Chất, Lõi Hồi Tố Linh Hồn, Nguyên Hình Thị Giới, v.v.) cũng như phương thức ngẫu nhiên (bao gồm Bắt Nguyên Chất·Thiên Vong, v.v.), sẽ không chuyển đổi Ngưng Tụ Căn Nguyên.\n·Lần gọi này thuộc【Gọi sự kiện nhân vật】, trong bất kỳ【Gọi sự kiện nhân vật】nào, số lần gọi bảo đáy sẽ được tích lũy chung, và được thống kê độc lập với số lần gọi bảo đáy của các loại gọi khác.\n\n"
  },
