  Summon_77961_ShortDesc = {
    Text = "Chắc chắn nhận được thân thể được đánh thức là <SummonBlue:biển sâu> lãnh vực"
  },
  Summon_77961_Title = {
    Text = "Xoáy Nước Chìm Đắm"
  },
  Summon_77962_Desc = {
    Text = "Mỗi <SummonPurple:5> lần thức tỉnh bắt buộc có đối tượng cấp SR hoặc cao hơn"
  },
  Summon_77962_LongDesc1 = {
    Text = "【<SummonPurple:Hư Huyền Dệt Mệnh>】Sự kiện có giới hạn thời gian thức tỉnh nhân vật đã mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh nhân vật UP giới hạn thời gian <SummonPurple:Arachne>.\n·Trong thời gian sự kiện, xác suất thức tỉnh của thể thức tỉnh SSR giới hạn <SummonPurple:Arachne> sẽ được nâng cao.\n·Trong sự kiện thức tỉnh giới hạn thời gian này, ngoài các quy tắc đặc biệt như nâng cao xác suất, bảo đảm, tất cả các thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định.\n·Khuyến nghị thức tỉnh hàng ngày: Trong sự kiện thức tỉnh giới hạn thời gian này, Người Giữ Gìn có thể thức tỉnh một lần với giá ưu đãi 60 nguồn lỏng mỗi ngày, và được tặng thêm 60 bạc tâm.\n\n<Title:【Điều chỉnh cân bằng】>\n·Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo sự vui vẻ và công bằng của trò chơi, có thể có điều chỉnh cân bằng làm yếu hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh.\n·Khi có sự yếu đi, trò chơi sẽ mở chức năng hồi tố có giới hạn thời gian để cho phép tái phân bổ tài nguyên cho việc phát triển hoặc thức tỉnh của thể thức tỉnh và vòng mệnh.\n·Xin hãy chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_77962_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong hoạt động nhân vật giới hạn 【<SummonPurple:Hư Huyền Chức Mệnh>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh sẽ đảm bảo nhận được thể thức tỉnh SSR qua bảo đảm.\n·Khi nhận được thể thức tỉnh SSR qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonPurple:Arachne> của đợt này.\n·Nếu liên tiếp 2 lần thức tỉnh nhận được thể thức tỉnh SSR không phải là nhân vật nâng cao xác suất trong đợt này, lần thức tỉnh tiếp theo nhận được nhân vật SSR chắc chắn sẽ là nhân vật nâng cao xác suất trong đợt này.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải là UP trong đợt này.{s3}\n\n<Title:【SR vật phẩm】>\nTrong hoạt động thức tỉnh nhân vật 【<SummonPurple:Hư Huyền Chức Mệnh>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n·Tối đa 5 lần thức tỉnh sẽ đảm bảo nhận được vật phẩm SR hoặc cao hơn qua bảo đảm, xác suất nhận được vật phẩm SR qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Thông báo đặc biệt】>\n·Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n·Bất kể qua hình thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, quà tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 nhận được thể thức tỉnh SSR giống nhau, mỗi lần sẽ chuyển đổi thành 1 mảnh tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ được chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và 「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ được chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh thừa của thể thức tỉnh qua hình thức tùy chọn (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, chân trời nguyên mẫu, v.v.) cũng như hình thức ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n·Lần thức tỉnh này thuộc loại 【thức tỉnh hoạt động nhân vật】, trong bất kỳ 【thức tỉnh hoạt động nhân vật】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
