  Summon_77963_ShortDesc = {
    Text = "Được thân thể được đánh thức chắc chắn là <SummonRed:thịt máu> giới vực"
  },
  Summon_77963_Title = {
    Text = "Sương Đêm Hoan Lạc"
  },
  Summon_77964_Desc = {
    Text = "Mỗi <SummonPurple:5> lần thức tỉnh bắt buộc có đối tượng cấp SR hoặc cao hơn"
  },
  Summon_77964_LongDesc1 = {
    Text = "【<SummonPurple:Thánh Tâm Tẩy Thế>】Sự kiện hoạt động nhân vật giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể từ đó thức tỉnh nhân vật UP giới hạn thời gian <SummonPurple:Pollux>.\n· Trong thời gian sự kiện, tỷ lệ nhận được thể thức tỉnh SSR giới hạn <SummonPurple:Pollux> sẽ được tăng lên.\n· Trong lần thức tỉnh sự kiện giới hạn này, ngoại trừ các quy tắc đặc biệt như tỷ lệ kích hoạt tăng lên, bảo đảm, v.v., tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng tỷ lệ cơ bản, cụ thể theo quy định đã được nêu rõ.\n· Đề xuất thức tỉnh hàng ngày: Trong lần thức tỉnh sự kiện giới hạn này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với 60 nguồn lỏng và được tặng thêm 60 bạc tâm.\n\n<Title:【Điều chỉnh cân bằng】>\n· Do cách chơi của trò chơi đặc biệt, nhằm đảm bảo sự vui vẻ và công bằng của trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh, vòng mệnh.\n· Khi có sự giảm thiểu, trò chơi sẽ mở tính năng hồi phục giới hạn thời gian để cho phép việc phát triển hoặc thức tỉnh của thể thức tỉnh, vòng mệnh có cơ hội tái phân bổ tài nguyên.\n· Vui lòng chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên. \n\n"
  },
  Summon_77964_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện hoạt động nhân vật【<SummonPurple:Thánh Tâm Tẩy Thế>】giới hạn thời gian, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR qua bảo đảm.\n·Khi nhận được thể thức tỉnh SSR qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR <SummonPurple:Pollux> trong đợt này.\n·Nếu liên tiếp 2 lần thức tỉnh nhận được thể thức tỉnh SSR không phải là nhân vật trong đợt xác suất nâng cao này, thì lần thức tỉnh tiếp theo nhận được nhân vật SSR chắc chắn sẽ là nhân vật trong đợt xác suất nâng cao này.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải là nhân vật nâng cao trong đợt này.{s3}\n\n<Title:【SR vật phẩm】>\nTrong sự kiện hoạt động nhân vật【<SummonPurple:Thánh Tâm Tẩy Thế>】thức tỉnh, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n·Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn qua bảo đảm, xác suất nhận được vật phẩm SR qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n·Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n·Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 nhận được thể thức tỉnh SSR giống nhau, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 1 và 「Căn Nguyên Lắng Đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh Hồi Tố Linh Hồn」× 2 và「Căn Nguyên Lắng Đọng」× 250. Tuy nhiên, thông qua cách tùy chọn (bao gồm Khu vui chơi nguyên chất, Lõi Trở Lại Linh Hồn, Horizon Nguyên mẫu, v.v.) và phương thức ngẫu nhiên (bao gồm Bắt giữ nguyên chất·Bài Quên, v.v.) để nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh dư thừa sẽ không chuyển đổi căn nguyên lắng đọng.\n·Lần thức tỉnh này thuộc về【thức tỉnh hoạt động nhân vật】, trong bất kỳ lần【thức tỉnh hoạt động nhân vật】nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
