  Summon_78013_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_78013_LongDesc1 = {
    Text = "[<SummonOrange:Trái tim cứng như đá>] Sự kiện Vòng mệnh Thức tỉnh có thời gian giới hạn đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh UP có thời gian giới hạn <SummonOrange:Tự do không thể chịu đựng nổi>.\n· Trong thời gian sự kiện, xác suất thức tỉnh vòng mệnh SSR giới hạn <SummonOrange:Tự do không thể chịu đựng nổi> sẽ được nâng cao.\n\n· Trong lần thức tỉnh sự kiện có thời gian giới hạn này, ngoài việc kích hoạt xác suất nâng cao, bảo đảm và các quy tắc đặc biệt khác, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định được mô tả.\n· Khuyến nghị thức tỉnh hàng ngày: Trong lần thức tỉnh sự kiện có thời gian giới hạn này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với giá ưu đãi 60 nguồn lỏng và được tặng thêm 60 bạc tâm.\n\n<Title:[Điều chỉnh cân bằng]>\n· Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo sự vui vẻ và công bằng của trò chơi, có thể sẽ có điều chỉnh cân bằng để giảm hoặc tăng cường hiệu ứng của thể thức tỉnh và vòng mệnh.\n· Khi xảy ra giảm sức mạnh, trò chơi sẽ mở tính năng hồi phục có thời gian giới hạn để cho phép tái phân bổ tài nguyên cho việc nuôi dưỡng hoặc thức tỉnh thể thức tỉnh và vòng mệnh.\n· Vui lòng chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_78013_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện thức tỉnh vòng mệnh hạn chế 【<SummonOrange:Trái tim cứng như đá>】, xác suất cơ bản nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được vòng mệnh SSR thông qua bảo đảm.\n·Khi nhận được vòng mệnh SSR thông qua thức tỉnh, có 50.00% xác suất là vòng mệnh SSR <SummonOrange:Tự do không thể chịu đựng nổi> đang được tăng cường trong kỳ này.\n·Nếu vòng mệnh SSR nhận được trong lần thức tỉnh trước không phải là vòng mệnh có xác suất được tăng cường trong kỳ này, thì vòng mệnh SSR nhận được trong lần thức tỉnh tiếp theo chắc chắn sẽ là vòng mệnh có xác suất được tăng cường trong kỳ này.\n\n<Title:【SR vật phẩm】>\nTrong sự kiện thức tỉnh vòng mệnh 【<SummonOrange:Trái tim cứng như đá>】, xác suất cơ bản thức tỉnh vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n·Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n·Khi nhận được vòng mệnh SSR thông qua thức tỉnh, sẽ đồng thời nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n·Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, hệ thống tặng, v. v.) từ lần thứ 2~16 nhận được cùng một vòng mệnh SSR, mỗi lần sẽ tự động nâng cấp cấp độ chồng vị và nhận được 「căn nguyên lắng đọng」×50; từ lần thứ 17 trở đi, sẽ chuyển đổi thành 「mảnh hồi tố mệnh đồ」× 1,「căn nguyên lắng đọng」× 50,「phiếu vàng tường vi」× 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành 「mảnh hồi tố mệnh đồ」× 2,「căn nguyên lắng đọng」× 50,「phiếu vàng tường vi」× 20000. Tuy nhiên khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm Sách Luân Chuyển, Lõi Hồi Tố Mệnh Đồ, v. v.) cũng như phương thức ngẫu nhiên(bao gồm Định Cách Túc Mệnh·Thiên Vong, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n·Lần thức tỉnh này thuộc về 【Sự kiện Vòng mệnh Thức tỉnh】, trong bất kỳ lần 【Sự kiện Vòng mệnh Thức tỉnh】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung, và thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n"
  },
