  Summon_81451_ShortDesc = {
    Text = "Lần đầu tiên 5 lần thức tỉnh chắc chắn sẽ nhận được người đánh thức SSR"
  },
  Summon_81451_Title = {
    Text = "Sáng Đầu Bạc"
  },
  Summon_81492_Desc = {
    Text = "Mỗi<{s1}:5> lần đánh thức nhất định sẽ cho SR cấp hoặc đối tượng cao hơn"
  },
  Summon_81492_LongDesc1 = {
    Text = "[<SummonOrange:Lời gọi xa xưa>] sự kiện có giới hạn thời gian đã mở. Trong thời gian sự kiện, Người Giữ Gìn có thể từ đó <SummonOrange:chọn tự do> thể thức tỉnh và bánh xe định mệnh để nhận được xác suất nâng cao. \n· Sau khi thức tỉnh thể thức tỉnh chỉ định thông qua sứ mệnh theo thứ tự trong [Lời gọi xa xưa], có thể nhận được thể thức tỉnh và bánh xe định mệnh, nếu nhận được thể thức tỉnh, chắc chắn sẽ là thể thức tỉnh trong cõi của thể thức tỉnh đã chọn. \n\n· Trong thời gian sự kiện, xác suất thức tỉnh của <SummonOrange:thể thức tỉnh SSR và bánh xe định mệnh được đề cử> đã chọn sẽ tăng lên. \n· Trong lần thức tỉnh sự kiện có giới hạn thời gian này, ngoài các quy tắc đặc biệt như xác suất nâng cao, bảo đảm, v.v., tất cả thể thức tỉnh hoặc bánh xe định mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định. \n\n<Title:[Điều chỉnh cân bằng]>\n· Do tính chất đặc biệt của lối chơi, để đảm bảo sự vui vẻ và công bằng trong trò chơi, trò chơi có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng của thể thức tỉnh, bánh xe định mệnh. \n· Khi xảy ra giảm thiểu, trò chơi sẽ mở chức năng hồi phục có giới hạn thời gian để cho phép việc phát triển hoặc thức tỉnh của thể thức tỉnh, bánh xe định mệnh có cơ hội tái phân bổ tài nguyên. \n· Vui lòng đảm bảo rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên. \n\n"
  },
  Summon_81492_LongDesc2 = {
    Text = "<Title:[SSR vật phẩm]>\nTrong sự kiện giới hạn 【<SummonOrange:Lời gọi xa xưa>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Vật phẩm SSR nhận được là thể thức tỉnh hoặc vòng mệnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SSR thể thức tỉnh hoặc vòng mệnh được đề xuất thông qua bảo đảm.\n· Khi nhận được SSR thông qua thức tỉnh, có 33.33% xác suất là SSR <SummonOrange:thể thức tỉnh hoặc vòng mệnh được đề xuất> đã chọn trong kỳ này.\n· Nếu liên tiếp 2 lần thức tỉnh nhận được SSR không phải là thể thức tỉnh hoặc vòng mệnh SSR đã chọn trong kỳ này, thì lần thức tỉnh tiếp theo nhận được SSR chắc chắn sẽ là thể thức tỉnh hoặc vòng mệnh SSR đã chọn trong kỳ này.{s1}\n· Hiện tại đã liên tiếp {s2} lần nhận được thể thức tỉnh hoặc vòng mệnh không phải là đã chọn trong kỳ này.{s3}\n\n<Title:[SR vật phẩm]>\nTrong sự kiện thức tỉnh 【<SummonOrange:Lời gọi xa xưa>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n· Khi nhận được vòng mệnh SSR thông qua thức tỉnh, sẽ đồng thời nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR thông qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua phương thức nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi tại cửa hàng, quà tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Nhưng thông qua phương thức tùy chọn (bao gồm công viên nguyên chất, lõi trở lại linh hồn, chân trời nguyên mẫu, v.v.) cũng như phương thức ngẫu nhiên (bao gồm bắt giữ nguyên chất · bài quên, v.v.) để nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh dư thừa sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về 【Sứ mệnh theo thứ tự】, trong bất kỳ 【Sứ mệnh theo thứ tự】 nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn chung và được thống kê độc lập với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác.\n\n"
  },
