  Summon_81539_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong【<SummonOrange:Chưa bị quên lãng·Hỗn Mang>】hợp đồng mệnh quỹ đạo thức tỉnh, xác suất tổng hợp nhận được vật phẩm SSR là 100.00%. Vật phẩm SSR nhận được là 2 thể thức tỉnh và 3 vòng mệnh.\n·Khi nhận được thể thức tỉnh SSR qua thức tỉnh, có 100% xác suất là thể thức tỉnh thuộc cõi <SummonOrange:Hỗn Mang>.\n\n<Title:【Giải thích đặc biệt】>\n·Bất kể qua cách nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi trong cửa hàng, tặng từ hệ thống, v.v.) lần thứ 2~16 nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ thể thức tỉnh tương ứng và 50 căn nguyên lắng đọng; lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Tuy nhiên, khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh thừa qua bất kỳ cách nào (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, chân trời nguyên mẫu, v.v.) và cách ngẫu nhiên (bao gồm bắt giữ nguyên chất·Bài Quên, v.v.) sẽ không chuyển đổi căn nguyên lắng đọng."
  },
  Summon_81539_Name = {
    Text = "Thức tỉnh Hợp đồng Mệnh quỹ đạo"
