  Summon_81539_RateListTextSSR = {
    Text = "Tỷ lệ xuất hiện tối thiểu của vật phẩm SSR: 100.00%"
  },
  Summon_81539_ShortDesc = {
    Text = "Chắc chắn nhận được <SummonOrange:2> thể thức tỉnh giới hạn và <SummonOrange:3> bánh xe định mệnh giới hạn"
  },
  Summon_81539_Title = {
    Text = "Chưa bị quên lãng·Hỗn loạ"
  },
  Summon_89883_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh chắc chắn nhận được đối tượng SR hoặc cao hơn"
  },
  Summon_89883_LongDesc1 = {
    Text = "[<SummonOrange:Hành trình nghìn màn>] Thức tỉnh trăm tướng của chúng sinh đã được mở. Trong thời gian hoạt động, Người Giữ Gìn có thể thức tỉnh một số thân thể được đánh thức SSR giới hạn và một số vòng mệnh SSR giới hạn từ tất cả các cõi. \n· Trong lần thức tỉnh có giới hạn này, ngoài các quy tắc đặc biệt như tăng xác suất kích hoạt, bảo đảm, v.v., tất cả thân thể được đánh thức hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy tắc đã được thông báo. \n· Thức tỉnh hàng ngày được khuyến nghị: Trong lần thức tỉnh trăm tướng này, Người Giữ Gìn mỗi ngày có thể thức tỉnh một lần với giá ưu đãi 60 nguồn lỏng và được tặng thêm 60 bạc tâm. \n\n<Title:[Điều chỉnh cân bằng]> \n· Do lối chơi của game đặc biệt, để đảm bảo sự thú vị và công bằng của game, game có thể thực hiện điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng trong các thân thể được đánh thức và vòng mệnh. \n· Khi có sự giảm sút, game sẽ mở chức năng hồi phục có giới hạn để cho các thân thể được đánh thức và vòng mệnh có cơ hội tái phân bổ tài nguyên. \n· Vui lòng chắc chắn rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên. \n\n"
  },
  Summon_89883_LongDesc2 = {
    Text = "<Title:[Vật phẩm SSR]>\n·Trong [<SummonOrange:Hành trình nghìn màn>] thức tỉnh trăm tướng của chúng sinh, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Vật phẩm SSR nhận được là thể thức tỉnh hoặc vòng mệnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh hoặc vòng mệnh SSR thông qua bảo đảm.\n·Khi nhận được vật phẩm SSR qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR.\n·Nếu hai lần thức tỉnh liên tiếp nhận được SSR là vòng mệnh, lần thức tỉnh tiếp theo nhận được SSR chắc chắn sẽ là thể thức tỉnh.{s1}\n·Hiện tại đã liên tiếp {s2} lần nhận được thể thức tỉnh không phải SSR.{s3}\n\n<Title:[Vật phẩm SR]>\n·Trong [<SummonOrange:Hành trình nghìn màn>] thức tỉnh hoạt động nhân vật, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n·Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:[Giải thích đặc biệt]>\n·Khi nhận được vòng mệnh SSR qua thức tỉnh, sẽ đồng thời nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n·Dù thông qua bất kỳ phương thức nào(bao gồm nhưng không giới hạn ở thức tỉnh, đổi chác tại cửa hàng, quà tặng từ hệ thống, v. v.) lần thứ 2~16 nhận được vòng mệnh SSR giống nhau, mỗi lần sẽ tự động nâng cấp cấp độ xếp chồng và nhận được \"căn nguyên lắng đọng\" ×50; từ lần thứ 17 trở đi, sẽ chuyển đổi thành \"mảnh hồi tố mệnh đồ\" × 1,\"căn nguyên lắng đọng\" × 50,\"phiếu vàng tường vi\" × 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành \"mảnh hồi tố mệnh đồ\" × 2,\"căn nguyên lắng đọng\" × 50,\"phiếu vàng tường vi\" × 20000, lần thứ 2~16 nhận được thể thức tỉnh SSR giống nhau, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành \"mảnh hồi tố linh hồn\" × 1 và \"căn nguyên lắng đọng\" × 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành \"mảnh hồi tố linh hồn\" × 2 và \"căn nguyên lắng đọng\" × 250. Nhưng khi nhận được thể thức tỉnh hoặc mảnh vỡ thể thức tỉnh thừa thông qua các phương thức tùy ý(bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, horizon nguyên mẫu, v. v.) và phương thức ngẫu nhiên(bao gồm bắt giữ nguyên chất·bài quên, v. v.) sẽ không chuyển đổi căn nguyên lắng đọng.\n·Lần thức tỉnh này thuộc về [thức tỉnh trăm tướng của chúng sinh], trong bất kỳ [thức tỉnh trăm tướng của chúng sinh] nào, số lần thức tỉnh bảo đảm sẽ được tích lũy chung, và độc lập thống kê với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác. \n\n"
  },
