  Summon_97303_ShortDesc = {
    Text = "Chắc chắn nhận được thân thể được đánh thức là <SummonBlue:biển sâu> lãnh vực"
  },
  Summon_97303_Title = {
    Text = "Sự giáng sinh của vực thẳm"
  },
  Summon_97304_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_97304_LongDesc1 = {
    Text = "【<SummonOrange:Đại yến ca>】Sự kiện Vòng Sinh Mệnh giới hạn đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh giới hạn của sự kiện <SummonOrange:Lệnh cấm của nữ hoàng>. \n·Trong thời gian sự kiện, xác suất thức tỉnh và nhận vòng mệnh SSR giới hạn <SummonOrange:Lệnh cấm của nữ hoàng> sẽ được tăng lên. \n·Sau khi sự kiện kết thúc, vòng mệnh SSR giới hạn <SummonOrange:Lệnh cấm của nữ hoàng> vẫn sẽ xuất hiện trong các sự kiện thức tỉnh vòng mệnh giới hạn sau 3 - 9 tháng kể từ lần UP đầu tiên, cho đến khoảng một năm sau khi nó vào [Vòng quay thường trú]. \n·Trong lần thức tỉnh giới hạn này, ngoài các quy tắc đặc biệt như tăng xác suất thức tỉnh và bảo đảm, tất cả các thân thể được đánh thức hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể xem theo Quy tắc giải thích. \n\n<Title:[Điều chỉnh cân bằng]>\n·Do tính chất chơi game đặc biệt, để đảm bảo niềm vui và công bằng trong trò chơi, trò chơi có thể thực hiện các điều chỉnh cân bằng như giảm hoặc tăng cường hiệu ứng của các thân thể được đánh thức hoặc vòng mệnh. \n·Khi xảy ra việc giảm sức mạnh, trò chơi sẽ mở chức năng hồisuyệt giới hạn để cho phép người chơi có cơ hội tái phân bổ tài nguyên cho việc thức tỉnh hoặc nâng cấp các thân thể được đánh thức hoặc vòng mệnh. \n·Hãy chắc chắn rằng bạn đã hiểu và chấp nhận điểm này trước khi đầu tư tài nguyên. \n\n"
  },
  Summon_97304_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện vòng mệnh giới hạn【<SummonOrange:Tiệc Âm Thanh>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần hoán tỉnh chắc chắn sẽ nhận được vòng mệnh SSR thông qua bảo đảm.\n· Khi nhận được vòng mệnh SSR thông qua hoán tỉnh, có 50.00% xác suất là vòng mệnh SSR【<SummonOrange:Sắc lệnh nữ hoàng>】của kỳ này.\n· Nếu vòng mệnh SSR nhận được trong lần hoán tỉnh trước không phải là vòng mệnh có xác suất nâng cao của kỳ này, thì vòng mệnh SSR nhận được trong lần hoán tỉnh tiếp theo chắc chắn sẽ là vòng mệnh có xác suất nâng cao của kỳ này.\n\n<Title:【SR vật phẩm】>\nTrong sự kiện hoán tỉnh vòng mệnh【<SummonOrange:Tiệc Âm Thanh>】, xác suất cơ bản để hoán tỉnh vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần hoán tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần hoán tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Chú thích đặc biệt】>\n· Khi hoán tỉnh nhận được vòng mệnh SSR, sẽ đồng thời nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn ở hoán tỉnh, đổi trong cửa hàng, hệ thống tặng, v. v.) từ lần thứ 2~16 nhận được cùng một vòng mệnh SSR, mỗi lần sẽ tự động nâng cấp cấp độ xếp chồng và nhận được 「Căn nguyên lắng đọng」×50; từ lần thứ 17 trở đi, sẽ chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 1,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành 「Mảnh hồi tố mệnh đồ」× 2,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000. Tuy nhiên khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm Sách luân chuyển, Lõi hồi tố mệnh đồ, v. v.) cũng như phương thức ngẫu nhiên(bao gồm Định cách số mệnh·Thiên vong, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần hoán tỉnh này thuộc về【Sự kiện Vòng mệnh Thức tỉnh】, trong bất kỳ【Sự kiện Vòng mệnh Thức tỉnh】nào, số lần hoán tỉnh bảo đảm sẽ được tích lũy chung, và sẽ được thống kê độc lập với số lần hoán tỉnh bảo đảm của các loại hoán tỉnh khác.\n"
  },
