  Summon_98325_Desc = {
    Text = "Mỗi <SummonOrange:5> lần thức tỉnh luôn có SR cấp hoặc cao hơn vòng mệnh"
  },
  Summon_98325_LongDesc1 = {
    Text = "[<SummonOrange:Xâm phạm Thánh Ca>] Sự kiện Vòng mệnh Thức tỉnh có giới hạn thời gian đã được mở. Trong thời gian sự kiện, Người Giữ Gìn có thể thức tỉnh vòng mệnh UP giới hạn thời gian <SummonOrange:Khúc cầu hồn vĩnh cửu>.\n·Trong thời gian sự kiện, xác suất nhận được vòng mệnh SSR giới hạn <SummonOrange:Khúc cầu hồn vĩnh cửu> sẽ được tăng cường.\n·Sau khi sự kiện kết thúc, vòng mệnh SSR giới hạn <SummonOrange:Khúc cầu hồn vĩnh cửu> vẫn sẽ xuất hiện trong sự kiện Vòng mệnh Thức tỉnh giới hạn thời gian sau lần UP đầu tiên trong khoảng 3 - 9 tháng, cho đến khi vào khoảng một năm sau sẽ xuất hiện trong [Pha Quay] Thức tỉnh vòng mệnh thường trực.\n·Trong sự kiện Thức tỉnh giới hạn thời gian này, ngoài việc kích hoạt xác suất tăng cường, bảo đảm và các quy tắc đặc biệt khác, tất cả thể thức tỉnh hoặc vòng mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy định đã nêu.\n\n<Title:[Điều chỉnh cân bằng]>\n·Do cách chơi của trò chơi có tính đặc thù, nhằm đảm bảo niềm vui và tính công bằng của trò chơi, trò chơi có thể thực hiện các điều chỉnh cân bằng để giảm hoặc tăng hiệu ứng trong thể thức tỉnh, vòng mệnh.\n·Khi có sự giảm sút, trò chơi sẽ mở chức năng hồi tưởng có giới hạn thời gian để cho phép thể thức tỉnh, vòng mệnh có cơ hội tái phân bổ tài nguyên.\n·Vui lòng đảm bảo rằng bạn đã biết và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_98325_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong sự kiện vòng mệnh giới hạn【<SummonOrange:Xâm phạm Thánh Ca>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp(bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là vòng mệnh, tối đa 30 lần hoán tỉnh chắc chắn sẽ nhận được vòng mệnh SSR thông qua bảo đảm.\n· Khi nhận được vòng mệnh SSR thông qua hoán tỉnh, có 50.00% xác suất là vòng mệnh SSR【<SummonOrange:Khúc cầu hồn vĩnh cửu>】đang UP trong kỳ này.\n· Nếu vòng mệnh SSR nhận được trong lần hoán tỉnh trước không phải là vòng mệnh có xác suất nâng cao trong kỳ này, thì vòng mệnh SSR nhận được trong lần hoán tỉnh tiếp theo chắc chắn sẽ là vòng mệnh có xác suất nâng cao trong kỳ này.\n\n<Title:【SR vật phẩm】>\nTrong sự kiện hoán tỉnh vòng mệnh【<SummonOrange:Xâm phạm Thánh Ca>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp(bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần hoán tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần hoán tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn thông qua bảo đảm, xác suất nhận được vật phẩm SR thông qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n· Khi nhận được vòng mệnh SSR, sẽ đồng thời nhận được 50 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh SR, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Bất kể thông qua phương thức nào(bao gồm nhưng không giới hạn hoán tỉnh, đổi tại cửa hàng, hệ thống tặng, v. v.) từ lần thứ 2~16 nhận được cùng một vòng mệnh SSR, mỗi lần sẽ tự động nâng cấp cấp độ xếp chồng và nhận được「Căn nguyên lắng đọng」×50; từ lần thứ 17 trở đi, sẽ chuyển đổi thành「Mảnh hồi tố mệnh đồ」× 1,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000, vòng mệnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tố mệnh đồ」× 2,「Căn nguyên lắng đọng」× 50,「Phiếu vàng tường vi」× 20000. Nhưng khi nhận được vòng mệnh thông qua phương thức tự chọn(bao gồm Sách luân chuyển, Lõi hồi tố mệnh đồ, v. v.) cũng như phương thức ngẫu nhiên(bao gồm Định hình số mệnh·Thiên vong, v. v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần hoán tỉnh này thuộc loại【hoán tỉnh vòng mệnh】, trong bất kỳ lần hoán tỉnh nào của【hoán tỉnh vòng mệnh】, số lần hoán tỉnh bảo đảm sẽ được cộng dồn lại, và sẽ độc lập thống kê với số lần hoán tỉnh bảo đảm của các loại hoán tỉnh khác.\n"
  },
