  Summon_98443_Desc = {
    Text = "Mỗi <SummonBlue:5> lần thức tỉnh đảm bảo nhận được đối tượng cấp SR hoặc cao hơn"
  },
  Summon_98443_LongDesc1 = {
    Text = "【<SummonBlue:Hỏa thiên dẫn đường>】Sự kiện hoạt động nhân vật thức tỉnh giới hạn đã mở. Trong thời gian hoạt động, người giữ gìn có thể thức tỉnh nhân vật UP có thời gian giới hạn <SummonBlue:Khop Sanga>.\n· Trong thời gian hoạt động, xác suất thức tỉnh nhân vật SSR giới hạn <SummonBlue:Khop Sanga> sẽ được nâng cao.\n\n· Trong lần thức tỉnh sự kiện giới hạn này, mọi nhân vật thức tỉnh hoặc bánh xe định mệnh đều sử dụng xác suất cơ bản, cụ thể theo quy tắc đã được nêu.\n\n<Title:【Điều chỉnh cân bằng】>\n· Do cách chơi đặc biệt của trò chơi, nhằm đảm bảo vui vẻ và công bằng, trò chơi có thể tiến hành điều chỉnh cân bằng nhằm giảm yếu hoặc tăng cường hiệu ứng của nhân vật thức tỉnh, bánh xe định mệnh.\n· Khi xảy ra giảm yếu, trò chơi sẽ mở chức năng hồi tưởng giới hạn để cho phép nhân vật thức tỉnh, bánh xe định mệnh có cơ hội tái phân bố tài nguyên trong quá trình phát triển hoặc thức tỉnh.\n· Xin hãy chắc chắn rằng bạn hiểu và chấp nhận điều này trước khi đầu tư tài nguyên.\n\n"
  },
  Summon_98443_LongDesc2 = {
    Text = "<Title:【SSR vật phẩm】>\nTrong hoạt động thức tỉnh nhân vật có thời hạn【<SummonBlue:Đạo Hỏa Thiên Không>】, xác suất cơ bản để nhận được vật phẩm SSR là 3.03%, xác suất tổng hợp (bao gồm bảo đảm) là 5.02%. Tất cả vật phẩm SSR nhận được đều là thể thức tỉnh, tối đa 30 lần thức tỉnh chắc chắn sẽ nhận được thể thức tỉnh SSR qua bảo đảm.\n· Khi nhận được thể thức tỉnh SSR qua thức tỉnh, có 33.33% xác suất là thể thức tỉnh SSR<SummonBlue:Crépésant> đang UP trong kỳ này.\n· Nếu liên tiếp 2 lần thức tỉnh nhận được thể thức tỉnh SSR không phải là nhân vật có xác suất tăng trong kỳ này, thì lần thức tỉnh tiếp theo chắc chắn sẽ nhận được nhân vật có xác suất tăng trong kỳ này. {s1}\n· Hiện tại đã liên tiếp {s2} lần nhận được nhân vật không phải là nhân vật UP trong kỳ này. {s3}\n\n<Title:【SR vật phẩm】>\nTrong hoạt động thức tỉnh nhân vật【<SummonBlue:Đạo Hỏa Thiên Không>】, xác suất cơ bản để nhận được vật phẩm SR là 15.85%, xác suất tổng hợp (bao gồm bảo đảm) là 25.00%. Tất cả vật phẩm SR trong lần thức tỉnh này đều là vòng mệnh.\n· Tối đa 5 lần thức tỉnh chắc chắn sẽ nhận được vật phẩm SR hoặc cao hơn qua bảo đảm, xác suất nhận được vật phẩm SR qua bảo đảm là 96.97%, xác suất nhận được vật phẩm SSR là 3.03%.\n\n<Title:【Giải thích đặc biệt】>\n· Khi nhận được vòng mệnh SR qua thức tỉnh, sẽ đồng thời nhận được 5 căn nguyên lắng đọng như sản phẩm phụ; khi nhận được vòng mệnh R, sẽ đồng thời nhận được 1 căn nguyên lắng đọng như sản phẩm phụ.\n· Dù nhận được bằng cách nào (bao gồm nhưng không giới hạn ở thức tỉnh, đổi ở cửa hàng, quà tặng từ hệ thống, v.v.) từ lần thứ 2 đến lần thứ 16 khi nhận được cùng một thể thức tỉnh SSR, mỗi lần sẽ chuyển đổi thành 1 mảnh vỡ tương ứng của thể thức tỉnh và 50 căn nguyên lắng đọng; từ lần thứ 17 trở đi, thể thức tỉnh SSR không giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 1 và「Căn nguyên lắng đọng」× 150, thể thức tỉnh SSR giới hạn sẽ chuyển đổi thành「Mảnh hồi tố linh hồn」× 2 và「Căn nguyên lắng đọng」× 250. Nhưng khi nhận được thể thức tỉnh hoặc mảnh vỡ thừa của thể thức tỉnh bằng các phương thức tùy chọn (bao gồm khu vui chơi nguyên chất, lõi trở lại linh hồn, chân trời nguyên mẫu, v.v.) và phương thức ngẫu nhiên (bao gồm bắt giữ nguyên chất·bài quên, v.v.), sẽ không chuyển đổi căn nguyên lắng đọng.\n· Lần thức tỉnh này thuộc về【thức tỉnh hoạt động nhân vật】, trong bất kỳ【thức tỉnh hoạt động nhân vật】nào, số lần thức tỉnh bảo đảm sẽ được cộng dồn, và độc lập thống kê với số lần thức tỉnh bảo đảm của các loại thức tỉnh khác. \n\n"
  },
